      "path": "src/service.ts",
      "content": "/**\n * Pet host service — the `pet.*` RPC domain. A composition facade: it wires\n * the pure event projection (`event-projection`) onto the state machine,\n * delegates the affinity economy to the ledger (`ledger`), and routes\n * persistence through `persist`. The API gateway maps these methods onto\n * `pet.state` / `pet.pets` / `pet.interact` / `pet.setVisible` /\n * `pet.setConfig` / `pet.setName` / `pet.setPet` for browser consumers.\n *\n * Concurrent sessions each keep their own machine: the sprite animation\n * follows the most recent meaningful event (the display session) while the\n * state view carries one bubble per active session.\n * @module @linxin666/dsh-pet/service\n */\n\nimport { Context, Service } from '@deepseek-ai/cordis'\nimport type { AssistantStreamFrame } from '@deepseek-ai/dsh-agent'\nimport type { Session, SessionEvent } from '@deepseek-ai/dsh-session'\nimport type { AffinityConfig, AffinityRankName, PetAffinityView, PetInteraction } from './affinity.ts'\nimport { announcementFresh, MAX_ANNOUNCEMENTS, parseAnnouncement, type PetAnnouncement } from './announce.ts'\nimport type { TreatConfig } from './treats.ts'\nimport {\n  emptyProjectionRuntime,\n  isActivityPhase,\n  projectAssistantStreamFrame,\n  projectOfficialEvent,\n  type ActivityStatusEventLike,\n  type ProjectionRuntime,\n} from './event-projection.ts'\nimport { PetLedger, type LedgerConfig, type LedgerInteractionResult } from './ledger.ts'\nimport { PanelActionRegistry, type PetPanelActionRegistration, type PetPanelActionView } from './panel-actions.ts'\nimport {\n  DEFAULT_PET_NAME,\n  DISPLAY_INSET_MAX,\n  DISPLAY_SIZE_MAX,\n  BUBBLE_SCALE_MAX,\n  BUBBLE_SCALE_MIN,\n  DISPLAY_SIZE_MIN,\n  PET_NAME_MAX_LENGTH,\n  loadPetPersist,\n  petHomeDir,\n  savePetPersist,\n  type PetDisplayConfig,\n} from './persist.ts'\nimport {\n  DEFAULT_DECORATION_ID,\n  decorationView,\n  loadPetRegistry,\n  petEntryView,\n  petPackageRoot,\n  type PetDefinition,\n  type PetEntry,\n  type PetManifest,\n  type PetRegistry,\n  type PetRegistryDiagnostic,\n} from './registry.ts'\nimport { WHISPER_TTL_MS, type VoicePackOverrides, type VoicePoolsProvider } from './chatter.ts'\nimport { mergeVoicePacks } from './voice-pack.ts'\nimport type { PetRemarks } from './remarks.ts'\nimport type { DecorationView } from './contracts/status-decoration.ts'\nimport {\n  defaultPetStateConfig,\n  PetStateMachine,\n  type PetStateConfig,\n  type PetStateInput,\n  type PetStateSnapshot,\n} from './state.ts'\nimport {\n  applyGameplayEffects,\n  drawLotteryTier,\n  initialGameplayState,\n  isDeclaredMode,\n  rollTouchBranch,\n  rollWorkOutcome,\n  settleGameplay,\n  type PetGameplayManifest,\n  type PetGameplayState,\n} from './gameplay.ts'\n\n/** The unified gameplay currency: the shared treat (小鱼干) ledger. */\nconst GAMEPLAY_TREATS_CURRENCY = 'treats'\n\n/** Plugin configuration. */\nexport interface PetConfig {\n  /** Affinity tuning. */\n  affinity?: Partial<AffinityConfig>\n  /** State machine tuning. */\n  state?: Partial<PetStateConfig>\n  /** Treat economy tuning. */\n  treats?: Partial<TreatConfig>\n  /** Persistence directory override (defaults to $DSH_HOME). */\n  persistDir?: string\n  /** Master switch for the plugin (browser half + host routes). */\n  enabled?: boolean\n  /** Status-decoration master switch (pet-center M5, #567); defaults to on. */\n  decorationEnabled?: boolean\n  /** Whether the pet's own session/status bubbles render (issue #6); defaults to 'auto'. */\n  statusBubbles?: PetStatusBubbleMode\n  /** Prebuilt registry (tests); defaults to scanning the package + user dirs. */\n  registry?: PetRegistry\n  /** Extra manifest entries composed by the embedding application. */\n  pets?: readonly PetManifest[]\n}\n\n/**\n * The pet's settings-namespace section: the pet selection and display fields\n * the web settings surface edits. `right`/`bottom` are also updated by drag\n * interactions, which keep the settings document in sync through the service.\n * Naming is per pet and lives outside the settings document (the hover-panel\n * rename targets the selected pet).\n */\nexport interface PetSettingsSection {\n  /** Selected pet id (a registry entry; the service clamps stale values). */\n  petId?: string\n  /** Master switch. */\n  visible: boolean\n  /** Scale of the rendered pet in px (sprite cell height). */\n  size: number\n  /** Horizontal inset from the viewport right edge, px. */\n  right: number\n  /** Vertical inset from the viewport bottom edge, px. */\n  bottom: number\n  /** Bubble typography multiplier (#1549); see PetDisplayConfig. */\n  bubbleScale?: number\n  /** Master switch for the plugin (browser half + host routes). */\n  enabled?: boolean\n  /**\n   * Status-decoration master switch (pet-center M5, #567). Defaults to on;\n   * the settings surface mirrors this field and can turn it off.\n   */\n  decorationEnabled?: boolean\n  /** Whether the pet's own session/status bubbles render (issue #6). */\n  statusBubbles?: PetStatusBubbleMode\n}\n\n/**\n * Whether the pet renders its own session/status bubbles (issue #6).\n *\n * `auto` is the shipped behavior: every active session keeps a bubble, and a\n * sibling plugin's announcement bubble rides the same stack above them. `off`\n * hides ONLY the pet's own bubbles — the announcement bubble, the interaction\n * feedback bubble and the sprite itself are untouched — which is what a plugin\n * that drives its own bubble surface needs. Anything unknown resolves to\n * `auto`, so an older profile or a hand-edited settings document keeps the\n * status bubbles rather than losing them silently.\n */\nexport type PetStatusBubbleMode = 'auto' | 'off'\n\n/** Every accepted {@link PetStatusBubbleMode}, in settings-card order. */\nexport const STATUS_BUBBLE_MODES: readonly PetStatusBubbleMode[] = ['auto', 'off']\n\n/** The shipped default; the switch changes nothing until a user turns it off. */\nexport const DEFAULT_STATUS_BUBBLE_MODE: PetStatusBubbleMode = 'auto'\n\n/**\n * Normalize a stored, live or hand-edited bubble mode.\n * @param value - the value the settings document carries, when any.\n * @returns the effective mode; anything but 'off' renders the bubbles.\n */\nexport function statusBubbleMode(value: unknown): PetStatusBubbleMode {\n  return value === 'off' ? 'off' : DEFAULT_STATUS_BUBBLE_MODE\n}\n\n/** Settings namespace of the pet capability. Spelled here rather than imported: the browser half spells the same value. */\nexport const PET_SETTINGS_NAMESPACE = 'pet'\n\n/**\n * One active TOP-LEVEL session as the pet displays it. Sessions run in\n * parallel, so each gets its own bubble while the sprite itself follows the\n * most recent meaningful event (the display session). Subagent children\n * report no bubble of their own: their work is already reflected by the\n * bubble of the conversation that spawned them, and the bubble buttons\n * navigate to GUI sessions, which subagents are not.\n */\nexport interface PetSessionView {\n  /** Session identity (stringified for the wire; never exposed as a key). */\n  sessionId: string\n  /** The animation this session's activity maps onto. */\n  animation: PetStateSnapshot['animation']\n  /** This session's status bubble copy. */\n  bubble: string\n  /** This session's raw activity phase. */\n  phase: PetStateSnapshot['phase']\n  /** This session's fresh inner whisper (碎碎念), when one is within its TTL. */\n  whisper?: string\n}\n\n/** Hard cap on simultaneously displayed session bubbles (most recent first). */\nexport const MAX_SESSION_BUBBLES = 12\n\n/** Snapshot returned by `pet.state`. */\nexport interface PetStateView {\n  animation: PetStateSnapshot['animation']\n  bubble?: string\n  phase: PetStateSnapshot['phase']\n  sessionActive: boolean\n  /**\n   * Per-session bubbles for every concurrently active TOP-LEVEL session:\n   * the GUI's current session first when reported, the rest most recently\n   * active first; optional so older hosts without the multi-session view\n   * stay consumable. The single 'bubble' above mirrors the display session.\n   */\n  sessions?: PetSessionView[]\n  /** Affinity ledger snapshot. */\n  affinity: PetAffinityView\n  /** Display configuration. */\n  display: PetDisplayConfig\n  /** The selected pet's registry identity. */\n  pet: {\n    /** Registry id. */\n    id: string\n    /** Manifest display name (unrenamed default). */\n    displayName: string\n    /** Manifest description. */\n    description: string\n  }\n  /** The selected pet's display name (user rename or manifest default). */\n  name: string\n  /**\n   * The selected frames2d skin id for this pet (absent = the pet's default\n   * look). Persisted host-side, so a page reload or client restart restores\n   * the user's last choice instead of falling back to the default look.\n   */\n  skin?: string\n  /** Treat (小鱼干) stock snapshot. */\n  treats: {\n    /** Stocked treats now. */\n    stocked: number\n    /** Stock cap. */\n    max: number\n  }\n  /**\n   * The active status decoration (pet-center M5, #567), when the master\n   * switch is on and the default decoration entry exists. Absent means the\n   * browser half renders no ornament.\n   */\n  decoration?: DecorationView\n  /**\n   * The selected pet's gameplay view (miku-pet generalization), present\n   * when the pet declares a gameplay block. Read-only projection: polling\n   * settles the view in memory but never writes pet.json.\n   */\n  gameplay?: PetGameplayStateView\n  /**\n   * The freshest plugin-authored announcement, within its TTL; absent when none\n   * is fresh. Rendered as a dedicated styled bubble above the session stack.\n   *\n   * Kept alongside `announcements` with exactly the meaning it had when the\n   * contract had a single slot, so a browser half predating the per-source\n   * upgrade keeps rendering one bubble instead of none (issue #1812). New\n   * readers should use `announcements`.\n   */\n  announcement?: PetAnnouncement\n  /**\n   * Every fresh plugin-authored announcement, one per publishing plugin, in\n   * render order (issue #1812). Absent when nothing is fresh, so a host with no\n   * publisher serves exactly what it served before the upgrade.\n   */\n  announcements?: PetAnnouncement[]\n  /**\n   * Whether the pet's own session/status bubbles render (issue #6). Absent\n   * on a host that predates the switch, which the browser half reads as\n   * `'auto'` — the behavior that shipped before it existed. Turning it to\n   * `'off'` hides those bubbles only; `announcement` and `bubble` (the\n   * legacy single status bubble) are still served, so the wire contract does\n   * not change with the display preference.\n   */\n  statusBubbles?: PetStatusBubbleMode\n  /**\n   * Actions a sibling plugin registered into the hover panel's action row\n   * (issue #6), in render order. Absent when none is registered, so the\n   * panel row is exactly what it was before the extension point existed.\n   */\n  panelActions?: PetPanelActionView[]\n}\n\n/** Result of `pet.interact`. */\nexport type PetInteractResult = LedgerInteractionResult\n\n/** The gameplay slice of the state view (dynamic state only; defs ride the pet definition). */\nexport interface PetGameplayStateView {\n  /** Stat values rounded for display. */\n  stats: Record<string, number>\n  /** Active mode id ('work' | 'sleep' | a declared extra mode) or null. */\n  mode: string | null\n}\n\n/** Result of the gameplay verbs (touch / setMode / workTick / buy). */\nexport interface PetGameplayVerbResult {\n  ok: boolean\n  error?: string\n  /** Touch: whether a branch hit, plus its presentation. */\n  hit?: boolean\n  state?: string\n  stateMs?: number\n  phrase?: string\n  /** Work tick outcome. */\n  outcome?: 'success' | 'fail'\n  /** Shop purchase: the drawn prize, when the item was a lottery. */\n  prize?: { amount: number; currency: string }\n  view?: PetGameplayStateView\n}\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    pet: PetService\n  }\n}\n/** Per-session pet activity: projection runtime plus the session's own machine. */\ninterface SessionActivity {\n  runtime: ProjectionRuntime\n  machine: PetStateMachine\n  /** The session's most recent meaningful input (for display fallback). */\n  lastInput?: PetStateInput\n  /** Latest inner whisper woken by this session's model output (碎碎念). */\n  whisper?: {\n    /** Whisper copy. */\n    text: string\n    /** Epoch ms when it appeared (view-side TTL applies). */\n    at: number\n  }\n}\n\n/**\n * Cordis service exposing the pet RPC domain. Lazy: nothing is scanned or\n * written until an economic event or interaction arrives; event listeners\n * update only in-memory state, and persistence happens on economic changes\n * (turn rewards, feeds, config/name changes) — never on a read.\n */\nexport class PetService extends Service {\n  static inject: string[] = []\n\n  private readonly machine: PetStateMachine\n  private readonly stateConfig: PetStateConfig\n  private readonly ledger: PetLedger\n  private readonly registry: PetRegistry\n  private readonly persistDir: string\n  private enabled: boolean\n  /** Status-decoration master switch (M5, #567); mirrored from settings. */\n  private decorationEnabled: boolean\n  /** Whether the pet renders its own session/status bubbles (issue #6). */\n  private statusBubbles: PetStatusBubbleMode\n  /**\n   * Plugin-authored announcements, one slot per `source` (issue #1812). The\n   * contract started as a single slot, where a second announcing plugin\n   * displaced the first; the map is the upgrade the design note predicted for\n   * exactly this moment. Insertion order is the render order and re-announcing\n   * a source updates its entry in place, so two publishers on different\n   * cadences never swap positions.\n   */\n  private readonly announcements = new Map<string, PetAnnouncement>()\n  private disposeActivity: (() => void) | undefined\n  /** Session whose most recent meaningful event currently drives the global pet. */\n  private displaySession: Session | undefined\n  /**\n   * Effective voice-pack overrides for the currently selected pet (M4,\n   * #677). Cached per pet id; the registry is an immutable snapshot, so the\n   * global pack and each entry's pack cannot change behind the cache.\n   */\n  private voiceCache: { petId: string; overrides: VoicePackOverrides } | undefined\n  /**\n   * Per-session activity, most recent last (Map insertion order). Bounded by\n   * MAX_SESSION_BUBBLES so a burst of sessions cannot grow it without bound;\n   * disposed sessions are removed by the 'session/disposed' listener.\n   */\n  private readonly sessionActivity = new Map<Session, SessionActivity>()\n  /**\n   * Hover-panel actions registered by sibling plugins (issue #6). The pet owns\n   * the panel row and serves the registrations; each plugin owns the callback a\n   * click dispatches to. Bounded, in-memory, reclaimed with the registering\n   * plugin's disposer.\n   */\n  private readonly panelActions = new PanelActionRegistry()\n  /**\n   * Sessions whose reward source is the official event stream. This metadata\n   * outlives transient visual resets so a derived legacy `done` cannot reward\n   * the same turn again after the pet is disabled and re-enabled.\n   */\n  private readonly officialEventSessions = new WeakSet<Session>()\n  /**\n   * Resolve the settings namespace this plugin's own config is served as, when\n   * the caller can read it off the composition. A plugin's settings ARE its own\n   * config, so the namespace is the row's id — and an aggregate bundle renames\n   * child rows (`pet` becomes `web-ui-pet`), which is why it cannot be assumed\n   * to be {@link PET_SETTINGS_NAMESPACE}. `apply` sets this; absent means the\n   * plugin runs outside a Loader and the package's own id stands.\n   */\n  settingsNamespaceProvider: (() => string | undefined) | undefined = undefined\n\n  constructor(ctx: Context, config: PetConfig = {}) {\n    super(ctx, 'pet')\n    this.persistDir = config.persistDir ?? petHomeDir()\n    this.registry = config.registry\n      ?? loadPetRegistry({\n        packageRoot: petPackageRoot(import.meta.url),\n        ...(config.pets === undefined ? {} : { extra: config.pets }),\n      })\n    if (this.registry.entries.length === 0) {\n      throw new Error('[dsh-pet] no valid pet manifests found; nothing to render')\n    }\n    let persist = loadPetPersist(this.persistDir)\n    if (this.registry.byId(persist.petId) === undefined) {\n      // The selected pet no longer exists (removed or a fresh install with a\n      // copied pet.json): fall back to the registry default.\n      persist = { ...persist, petId: this.registry.defaultEntry().id }\n    }\n    const selected = this.registry.byId(persist.petId) ?? this.registry.defaultEntry()\n    const ledgerConfig: LedgerConfig = {\n      affinity: config.affinity,\n      treats: config.treats,\n      ...this.voiceLayers(selected),\n    }\n    this.ledger = new PetLedger(persist, ledgerConfig)\n    this.stateConfig = { ...defaultPetStateConfig, ...(config.state ?? {}) }\n    this.machine = new PetStateMachine(this.stateConfig)\n    this.enabled = config.enabled ?? true\n    this.decorationEnabled = config.decorationEnabled ?? true\n    this.statusBubbles = statusBubbleMode(config.statusBubbles)\n\n    this.syncActivity()\n  }\n\n  /**\n   * The draw-time voice-pool provider handed to every projection runtime.\n   * It re-resolves when the selected pet changes, so live engines re-voice\n   * on the next draw without being rebuilt (M4, #677).\n   */\n  private voicePools(): VoicePoolsProvider {\n    return () => {\n      const entry = this.activeEntry()\n      if (this.voiceCache !== undefined && this.voiceCache.petId === entry.id) {\n        return this.voiceCache.overrides\n      }\n      const overrides = mergeVoicePacks(this.registry.globalVoice, entry.voice)?.overrides ?? {}\n      this.voiceCache = { petId: entry.id, overrides }\n      return overrides\n    }\n  }\n\n  /** Whether the pet service consumes session activity while enabled. */\n  isEnabled(): boolean {\n    return this.enabled\n  }\n\n  /**\n   * The voice layers one pet contributes to the ledger: its manifest remark\n   * pools first, then the voice packs (a pet directory's voice.json over the\n   * global `$DSH_HOME/pets/.voice.json`). The voice pack's `panel.ranks`\n   * ladder rides the same merge, so a ladder declared by either layer applies\n   * with the documented precedence. Every path that seats these layers\n   * resolves them here, so no call site can apply the manifest pools and\n   * silently drop the voice layer: doing that reverted a pet whose lines a\n   * voice pack had translated back to the built-in pools the moment the\n   * settings surface applied.\n   * @param entry - the pet whose layers apply.\n   * @returns the layers `PetLedger` takes.\n   */\n  private voiceLayers(entry: PetEntry): {\n    remarks?: PetRemarks\n    voiceRemarks?: PetRemarks\n    rankLadder?: readonly AffinityRankName[]\n  } {\n    const voice = mergeVoicePacks(this.registry.globalVoice, entry.voice)\n    return {\n      remarks: entry.remarks,\n      voiceRemarks: voice?.remarks,\n      rankLadder: voice?.panel?.ranks,\n    }\n  }\n\n  /** Re-seat the ledger's remark pools and rank ladder from one pet's layers. */\n  private applyVoiceLayers(entry: PetEntry): void {\n    const layers = this.voiceLayers(entry)\n    this.ledger.setRemarks(layers.remarks, layers.voiceRemarks)\n    this.ledger.setRankLadder(layers.rankLadder)\n  }\n\n  /** RPC: current pet state snapshot. */\n  async state(currentSessionId?: string): Promise<PetStateView> {\n    return this.view(currentSessionId)\n  }\n\n  /**\n   * RPC: one plugin-authored announcement bubble, held in the publisher's own\n   * slot keyed by `source` (issue #1812). The payload is validated into a\n   * bounded PetAnnouncement; a malformed one is dropped silently — a sibling\n   * plugin's bug must never surface as pet breakage. Re-announcing replaces\n   * only the caller's own slot, so publishers coexist instead of displacing\n   * each other. Announcements are in-memory only.\n   *\n   * The slot table is bounded by {@link MAX_ANNOUNCEMENTS}. Expired entries are\n   * pruned first, so a silent publisher never holds a slot; when the table is\n   * genuinely full, the entry that has been silent longest gives up its slot\n   * to the arriving one — a publisher that keeps refreshing is never evicted.\n   */\n  announce(input: unknown): { ok: boolean } {\n    const parsed = parseAnnouncement(input, Date.now())\n    if (parsed === undefined) return { ok: false }\n    const now = Date.now()\n    for (const [source, entry] of this.announcements) {\n      if (!announcementFresh(entry, now)) this.announcements.delete(source)\n    }\n    if (!this.announcements.has(parsed.source) && this.announcements.size >= MAX_ANNOUNCEMENTS) {\n      let oldest = ''\n      let oldestAt = Number.POSITIVE_INFINITY\n      for (const [source, entry] of this.announcements) {\n        if (entry.at < oldestAt) {\n          oldest = source\n          oldestAt = entry.at\n        }\n      }\n      if (oldest !== '') this.announcements.delete(oldest)\n    }\n    this.announcements.set(parsed.source, parsed)\n    return { ok: true }\n  }\n\n  /**\n   * The announcement slots still fresh, in render order. An expired entry\n   * simply stops appearing (the client's 2 s poll drops it); no timer owns its\n   * removal.\n   */\n  private freshAnnouncements(): PetAnnouncement[] {\n    const now = Date.now()\n    return [...this.announcements.values()].filter(entry => announcementFresh(entry, now))\n  }\n\n  /**\n   * Register one action into the hover panel's action row (issue #6). The pet\n   * renders the button and dispatches the click back to `onSelect`; the plugin\n   * decides what the button does. Registering is a wiring step, so a malformed\n   * registration throws at the caller's own apply instead of being dropped.\n   *\n   * The registration is reclaimed by the disposer, so the idiomatic call binds\n   * it to the registering plugin's fiber:\n   * ```ts\n   * ctx.effect(() => ctx.pet.registerPanelAction({\n   *   id: 'pet-quota-swap',\n   *   label: '换装',\n   *   onSelect: async () => { await cycleToNextPet(ctx.pet) },\n   * }))\n   * ```\n   * @param action - the registration to serve in the panel row.\n   * @returns a disposer that removes this registration.\n   * @throws when the id, label or callback is unusable, or the row is full.\n   */\n  registerPanelAction(action: PetPanelActionRegistration): () => void {\n    return this.panelActions.register(action)\n  }\n\n  /**\n   * RPC: dispatch one hover-panel action click back to the plugin that\n   * registered it. A rejected id is a stale click (the plugin disposed its\n   * registration between render and click), and a throwing callback is that\n   * plugin's own failure — neither may surface as pet breakage, so both answer\n   * `{ ok: false }` instead of throwing out of the route.\n   * @param id - the action id the browser half reported.\n   * @returns whether the click reached a registered action.\n   */\n  async selectPanelAction(id: string): Promise<{ ok: boolean; error?: string }> {\n    try {\n      const selected = await this.panelActions.select(id, { petId: this.selectedPetId() })\n      return selected ? { ok: true } : { ok: false, error: 'unknown-panel-action' }\n    } catch {\n      return { ok: false, error: 'panel-action-failed' }\n    }\n  }\n\n  /** Current persisted display config (read-only view). */\n  display(): PetDisplayConfig {\n    return { ...this.ledger.snapshot.display }\n  }\n\n  /** RPC: the registry entries the browser half renders and selects from. */\n  async pets(): Promise<PetDefinition[]> {\n    return this.registry.entries.map(entry => petEntryView(entry, this.registry.globalVoice))\n  }\n\n  /** The loaded registry (the asset routes serve its entries). */\n  registrySnapshot(): PetRegistry {\n    return this.registry\n  }\n\n  /** RPC: structured registry diagnostics (pet-center M2, issue #623). */\n  async diagnostics(): Promise<{ diagnostics: PetRegistryDiagnostic[] }> {\n    return { diagnostics: this.registry.diagnostics }\n  }\n\n  /**\n   * The active status decoration view (M5, #567): the default 'whale' entry\n   * (user directories override built-ins by id), gated by the master switch.\n   */\n  private activeDecoration(): DecorationView | undefined {\n    if (!this.decorationEnabled) return undefined\n    const entry = this.registry.decorationById?.(DEFAULT_DECORATION_ID)\n    return entry === undefined ? undefined : decorationView(entry)\n  }\n\n  /** The selected pet's registry entry. */\n  activeEntry(): NonNullable<PetRegistry['entries'][number]> {\n    return this.registry.byId(this.selectedPetId()) ?? this.registry.defaultEntry()\n  }\n\n  /** Currently selected pet id (persisted). */\n  selectedPetId(): string {\n    return this.ledger.snapshot.petId\n  }\n\n  /** The display name of one pet (user rename or manifest displayName). */\n  petName(petId: string = this.selectedPetId()): string {\n    const stored = this.ledger.snapshot.names[petId]\n    if (stored !== undefined && stored.trim() !== '') return stored\n    return this.registry.byId(petId)?.displayName ?? DEFAULT_PET_NAME\n  }\n\n  /** RPC: switch the selected pet (persisted, settings document mirrored). */\n  async setPetId(petId: string): Promise<{ ok: true; petId: string } | { ok: false; error: string }> {\n    const entry = this.registry.byId(petId)\n    if (entry === undefined) return { ok: false, error: 'unknown-pet' }\n    this.ledger.setPetId(entry.id)\n    this.applyVoiceLayers(entry)\n    this.flush()\n    this.syncSettingsFromPet()\n    return { ok: true, petId: entry.id }\n  }\n\n  /** Start or stop the session-activity listeners that drive the pet. */\n  setEnabled(enabled: boolean): void {\n    this.enabled = enabled\n    this.syncActivity()\n    if (!enabled) this.resetActivity()\n  }\n\n  private syncActivity(): void {\n    if (this.disposeActivity !== undefined) {\n      this.disposeActivity()\n      this.disposeActivity = undefined\n    }\n    if (!this.enabled) return\n    this.disposeActivity = (() => {\n      const disposers = [\n        this.ctx.on('session/event', (session: Session, event: SessionEvent) => {\n          const runtime = this.activityOf(session).runtime\n          // `activity/status` is an optional compatibility input. It is not\n          // declared as a durable event type by this package because current\n          // Harness installations publish the official session vocabulary.\n          if ((event.type as string) === 'activity/status') {\n            const payload = ((event as unknown as { data?: unknown }).data ?? {}) as ActivityStatusEventLike\n            if (typeof payload.phase !== 'string' || !isActivityPhase(payload.phase)) return\n            this.applyActivity(session, {\n              phase: payload.phase,\n              ...(typeof payload.line === 'string' ? { line: payload.line } : {}),\n              ...(typeof payload.phrase === 'string' ? { phrase: payload.phrase } : {}),\n            })\n            // On a legacy-only stream the compatibility event owns turn\n            // rewards. Once any official activity is observed, turn/end owns\n            // them and a derived legacy `done` cannot double-count.\n            if (payload.phase === 'done' && !runtime.officialEventsSeen) {\n              this.rewardLegacyTurn()\n            }\n            return\n          }\n\n          const transition = projectOfficialEvent(event, runtime)\n          if (transition === undefined) return\n          runtime.officialEventsSeen = true\n          this.officialEventSessions.add(session)\n          this.applyActivity(session, transition.input, transition.whisper)\n          if (transition.completedTurn !== undefined) {\n            this.rewardTurn(String(session.id), transition.completedTurn)\n          }\n        }),\n        this.ctx.on('agent/assistant-stream', ({ agent, frame }: { agent: { session: Session }; frame: AssistantStreamFrame }) => {\n          const session = agent.session\n          const runtime = this.activityOf(session).runtime\n          const transition = projectAssistantStreamFrame(frame, runtime)\n          if (transition === undefined) return\n          runtime.officialEventsSeen = true\n          this.officialEventSessions.add(session)\n          this.applyActivity(session, transition.input, transition.whisper)\n        }),\n        this.ctx.on('session/disposed', (session: Session) => {\n          this.ledger.forgetSession(String(session.id))\n          this.officialEventSessions.delete(session)\n          this.sessionActivity.delete(session)\n          if (session !== this.displaySession) return\n          // The display session is gone: fall back to the most recent\n          // remaining session's last input, or settle to idle when none.\n          this.displaySession = undefined\n          const remaining = [...this.sessionActivity.entries()].at(-1)\n          if (remaining !== undefined) {\n            const [nextSession, activity] = remaining\n            this.displaySession = nextSession\n            if (activity.lastInput !== undefined) this.machine.onActivityStatus(activity.lastInput)\n            this.machine.onSessionActive()\n          } else {\n            this.machine.onSessionDisposed()\n          }\n        }),\n      ]\n      return () => { for (const dispose of disposers) dispose() }\n    })()\n  }\n\n  /** Drop transient activity because terminal events missed while disabled cannot be replayed safely. */\n  private resetActivity(): void {\n    this.displaySession = undefined\n    this.sessionActivity.clear()\n    this.machine.onSessionDisposed()\n  }\n\n  /** Return the per-session activity record, creating it on first sight. */\n  private activityOf(session: Session): SessionActivity {\n    let activity = this.sessionActivity.get(session)\n    if (activity === undefined) {\n      const runtime = emptyProjectionRuntime(this.voicePools())\n      runtime.officialEventsSeen = this.officialEventSessions.has(session)\n      activity = {\n        runtime,\n        machine: new PetStateMachine(this.stateConfig),\n      }\n      this.sessionActivity.set(session, activity)\n    }\n    return activity\n  }\n\n  /**\n   * Commit one activity: the session's own machine renders its bubble, and\n   * the session becomes the host-global display session (most recent\n   * meaningful event wins the sprite animation).\n   */\n  private applyActivity(session: Session, input: PetStateInput, whisper?: string): void {\n    const activity = this.activityOf(session)\n    activity.lastInput = input\n    if (whisper !== undefined) activity.whisper = { text: whisper, at: Date.now() }\n    activity.machine.onActivityStatus(input)\n    activity.machine.onSessionActive()\n    // Move to the tail so map order reads most-recent-last, then trim the\n    // oldest session states beyond the bubble cap. The display session is\n    // reassigned below, so trimming its stale predecessor is safe.\n    this.sessionActivity.delete(session)\n    this.sessionActivity.set(session, activity)\n    while (this.sessionActivity.size > MAX_SESSION_BUBBLES) {\n      const oldest = this.sessionActivity.keys().next().value\n      if (oldest === undefined) break\n      this.sessionActivity.delete(oldest)\n    }\n    this.displaySession = session\n    this.machine.onActivityStatus(input)\n    this.machine.onSessionActive()\n  }\n\n  /** RPC: pet or feed the pet. */\n  async interact(kind: PetInteraction): Promise<PetInteractResult> {\n    const nowMs = Date.now()\n    const result = this.ledger.interact(kind, nowMs)\n    if (this.ledger.takeDirty()) this.flush()\n    return result\n  }\n\n  /* ---------------------------------------------------------------- *\n   * Gameplay verbs (miku-pet generalization). The manifest block lives\n   * on the registry entry; dynamic state persists per pet id. Verbs\n   * settle and persist; the state view projects without writing.\n   * ---------------------------------------------------------------- */\n\n  /** The active pet's gameplay block, if it declares one. */\n  private gameplayDef(): PetGameplayManifest | undefined {\n    return this.activeEntry().gameplay\n  }\n\n  /** The persisted (or fresh) gameplay state of the selected pet. */\n  private gameplayState(def: PetGameplayManifest, now: number): { petId: string; state: PetGameplayState } {\n    const petId = this.selectedPetId()\n    const stored = this.ledger.snapshot.gameplay[petId]\n    return {\n      petId,\n      state: stored === undefined\n        ? initialGameplayState(def, now)\n        // Spread first so the settle remainders (restoreCarryMs / incomeCarryMs)\n        // survive a verb. Enumerating the fields dropped them, so every verb\n        // floored the elapsed time and threw the remainder away -- which starves\n        // any interval longer than the gap between verbs (30 s sleep restore,\n        // 30 min passive income).\n        : { ...stored, stats: { ...stored.stats }, currencies: { ...stored.currencies } },\n    }\n  }\n\n  /** Display view of one gameplay state (rounded stats; treats ride the shared treat ledger). */\n  private gameplayViewOf(state: PetGameplayState): PetGameplayStateView {\n    const stats: Record<string, number> = {}\n    for (const [name, value] of Object.entries(state.stats)) stats[name] = Math.round(value)\n    // A persisted mode the manifest no longer declares (a pet.json edit after\n    // the pet was parked in it) reads as \"no mode\". Otherwise the client would\n    // latch a mode it cannot resolve: the mode chip prints a raw i18n key, and\n    // the client's roam roll — suppressed while any mode is active — would\n    // never fire again.\n    const def = this.gameplayDef()\n    const mode = state.mode !== null && def !== undefined && !isDeclaredMode(def, state.mode) ? null : state.mode\n    return { stats, mode }\n  }\n\n  /**\n   * Move gameplay 'treats' currency (the unified post-wallet currency) from\n   * the engine's settle work area into the shared treat ledger, capped by\n   * the stock cap. The engine keeps its generic currency record for settle\n   * math; this drain is the only bridge to the wallet-free economy.\n   */\n  private drainGameplayTreats(state: PetGameplayState): void {\n    const pending = Math.floor(state.currencies[GAMEPLAY_TREATS_CURRENCY] ?? 0)\n    delete state.currencies[GAMEPLAY_TREATS_CURRENCY]\n    if (pending > 0) this.ledger.grantTreats(pending)\n  }\n\n  /** Persist the mutated gameplay state of one verb call. */\n  private commitGameplay(petId: string, state: PetGameplayState): void {\n    this.ledger.setGameplay(petId, state)\n    if (this.ledger.takeDirty()) this.flush()\n  }\n\n  /**\n   * RPC: a touch on the pet. 'zone' names a touch zone (roll a branch);\n   * omitted means a plain click while a touch animation holds (clickBoost).\n   */\n  async gameplayTouch(zone?: string): Promise<PetGameplayVerbResult> {\n    const def = this.gameplayDef()\n    if (def === undefined) return { ok: false, error: 'no-gameplay' }\n    const now = Date.now()\n    const { petId, state } = this.gameplayState(def, now)\n    settleGameplay(state, def, now, { sessionActive: this.machine.render().sessionActive })\n    if (zone === undefined) {\n      const boost = def.touch?.clickBoost\n      if (boost === undefined) return { ok: false, error: 'no-touch' }\n      const amount = boost.min + Math.floor(Math.random() * (boost.max - boost.min + 1))\n      if (amount > 0) applyGameplayEffects(state, def, [{ stat: boost.stat, amount }])\n      this.drainGameplayTreats(state)\n      this.commitGameplay(petId, state)\n      return { ok: true, hit: false, view: this.gameplayViewOf(state) }\n    }\n    const target = def.touch?.zones.find(entry => entry.name === zone)\n    if (target === undefined) return { ok: false, error: 'unknown-zone' }\n    const branch = rollTouchBranch(target, Math.random)\n    if (branch === undefined) {\n      this.drainGameplayTreats(state)\n      this.commitGameplay(petId, state)\n      return { ok: true, hit: false, view: this.gameplayViewOf(state) }\n    }\n    if (branch.effects !== undefined) applyGameplayEffects(state, def, branch.effects)\n    const phrase = branch.phrases !== undefined && branch.phrases.length > 0\n      ? branch.phrases[Math.floor(Math.random() * branch.phrases.length)]\n      : undefined\n    this.drainGameplayTreats(state)\n    this.commitGameplay(petId, state)\n    return {\n      ok: true,\n      hit: true,\n      ...(branch.state === undefined ? {} : { state: branch.state }),\n      ...(branch.stateMs === undefined ? {} : { stateMs: branch.stateMs }),\n      ...(phrase === undefined ? {} : { phrase }),\n      view: this.gameplayViewOf(state),\n    }\n  }\n\n  /**\n   * RPC: enter or leave a gameplay mode (null clears it). Every mode the\n   * manifest declares is accepted: 'work', 'sleep', or one of the extra\n   * 'modes' entries (a bath, a play session…).\n   */\n  async gameplaySetMode(mode: string | null): Promise<PetGameplayVerbResult> {\n    const def = this.gameplayDef()\n    if (def === undefined) return { ok: false, error: 'no-gameplay' }\n    if (mode === 'work' && def.work === undefined) return { ok: false, error: 'no-work' }\n    if (mode === 'sleep' && def.sleep === undefined) return { ok: false, error: 'no-sleep' }\n    if (mode !== null && !isDeclaredMode(def, mode)) return { ok: false, error: 'unknown-mode' }\n    const now = Date.now()\n    const { petId, state } = this.gameplayState(def, now)\n    settleGameplay(state, def, now, { sessionActive: this.machine.render().sessionActive })\n    // Switching modes restarts the restore cadence: a leftover carry from the\n    // previous mode must not advance the new mode's first tick.\n    if (state.mode !== mode) state.restoreCarryMs = 0\n    state.mode = mode\n    this.drainGameplayTreats(state)\n    this.commitGameplay(petId, state)\n    return { ok: true, view: this.gameplayViewOf(state) }\n  }\n\n  /** RPC: one work-round adjudication (only while the work mode holds). */\n  async gameplayWorkTick(): Promise<PetGameplayVerbResult> {\n    const def = this.gameplayDef()\n    if (def?.work === undefined) return { ok: false, error: 'no-work' }\n    const now = Date.now()\n    const { petId, state } = this.gameplayState(def, now)\n    if (state.mode !== 'work') return { ok: false, error: 'not-working' }\n    settleGameplay(state, def, now, { sessionActive: this.machine.render().sessionActive })\n    const outcome = rollWorkOutcome(def.work, Math.random)\n    const effects = outcome === 'success' ? def.work.success?.effects : def.work.fail?.effects\n    if (effects !== undefined) applyGameplayEffects(state, def, effects)\n    this.drainGameplayTreats(state)\n    this.commitGameplay(petId, state)\n    return { ok: true, outcome, view: this.gameplayViewOf(state) }\n  }\n\n  /** RPC: buy one shop item (effects, currency swap, or a lottery draw). */\n  async gameplayBuy(itemId: string): Promise<PetGameplayVerbResult> {\n    const def = this.gameplayDef()\n    if (def === undefined) return { ok: false, error: 'no-gameplay' }\n    const item = def.shop?.items.find(entry => entry.id === itemId)\n    if (item === undefined) return { ok: false, error: 'unknown-item' }\n    const now = Date.now()\n    const { petId, state } = this.gameplayState(def, now)\n    settleGameplay(state, def, now, { sessionActive: this.machine.render().sessionActive })\n    // The unified currency is the shared treat ledger (wallet removed): shop\n    // prices and prizes ride the same balance the panel shows and feeding\n    // consumes, capped by the stock cap.\n    const treats = item.currency === GAMEPLAY_TREATS_CURRENCY\n    const balance = treats ? this.ledger.snapshot.treats.treats : (state.currencies[item.currency] ?? 0)\n    if (balance < item.price) {\n      return { ok: false, error: 'insufficient-funds', view: this.gameplayViewOf(state) }\n    }\n    if (treats) this.ledger.spendTreats(item.price)\n    else state.currencies[item.currency] = balance - item.price\n    if (item.effects !== undefined) applyGameplayEffects(state, def, item.effects)\n    let prize: PetGameplayVerbResult['prize']\n    if (item.lottery !== undefined) {\n      if (item.lottery.effects !== undefined) applyGameplayEffects(state, def, item.lottery.effects)\n      const tier = drawLotteryTier(item.lottery, Math.random)\n      const prizeCurrency = tier.currency ?? item.lottery.currency ?? item.currency\n      if (prizeCurrency === GAMEPLAY_TREATS_CURRENCY) this.ledger.grantTreats(tier.prize)\n      else state.currencies[prizeCurrency] = (state.currencies[prizeCurrency] ?? 0) + tier.prize\n      prize = { amount: tier.prize, currency: prizeCurrency }\n    }\n    this.drainGameplayTreats(state)\n    this.commitGameplay(petId, state)\n    return { ok: true, ...(prize === undefined ? {} : { prize }), view: this.gameplayViewOf(state) }\n  }\n\n  /** RPC: show or hide the pet. */\n  async setVisible(visible: boolean): Promise<{ ok: true; display: PetDisplayConfig }> {\n    this.ledger.setDisplay({ ...this.ledger.snapshot.display, visible })\n    this.flush()\n    this.syncSettingsFromPet()\n    return { ok: true, display: this.ledger.snapshot.display }\n  }\n\n  /**\n   * The persisted skin for one entry, when the manifest still declares it: a\n   * stale id (skin removed from the manifest, pet swapped) reads as \"default\"\n   * rather than pinning a track the browser half cannot resolve.\n   */\n  private persistedSkin(entry: NonNullable<PetRegistry['entries'][number]>): string | undefined {\n    const stored = this.ledger.petSkin(entry.id)\n    if (stored === undefined) return undefined\n    return entry.frames2d?.skins?.some(skin => skin.id === stored) === true ? stored : undefined\n  }\n\n  /**\n   * RPC: select the current pet's frames2d skin (`undefined` restores the\n   * pet's default look). The choice is stored per pet, so every later state\n   * view (reload, client restart, pet re-selection) serves it back.\n   */\n  async setSkin(skin: string | undefined): Promise<{ ok: true; skin?: string } | { ok: false; error: string }> {\n    const entry = this.activeEntry()\n    const declared = entry.frames2d?.skins ?? []\n    if (skin === undefined) {\n      this.ledger.setPetSkin(entry.id, undefined)\n      this.flush()\n      return { ok: true }\n    }\n    if (!declared.some(candidate => candidate.id === skin)) return { ok: false, error: 'unknown-skin' }\n    this.ledger.setPetSkin(entry.id, skin)\n    this.flush()\n    return { ok: true, skin }\n  }\n\n  /** RPC: update display config (size / position / bubble scale). Pixel values are clamped to whole pixels. */\n  async setConfig(patch: Partial<PetDisplayConfig>): Promise<{ ok: true; display: PetDisplayConfig }> {\n    const next = { ...this.ledger.snapshot.display, ...patch }\n    next.size = Math.round(Math.min(DISPLAY_SIZE_MAX, Math.max(DISPLAY_SIZE_MIN, next.size)))\n    next.right = Math.round(Math.min(DISPLAY_INSET_MAX, Math.max(0, next.right)))\n    next.bottom = Math.round(Math.min(DISPLAY_INSET_MAX, Math.max(0, next.bottom)))\n    next.bubbleScale = Math.min(BUBBLE_SCALE_MAX, Math.max(BUBBLE_SCALE_MIN, next.bubbleScale))\n    this.ledger.setDisplay(next)\n    this.flush()\n    this.syncSettingsFromPet()\n    return { ok: true, display: this.ledger.snapshot.display }\n  }\n\n  /** RPC: rename the selected pet (trimmed, 1–20 chars, per-pet storage). */\n  async setName(name: string): Promise<{ ok: true; name: string } | { ok: false; error: string }> {\n    const trimmed = name.trim()\n    if (trimmed === '') return { ok: false, error: 'name-empty' }\n    if (trimmed.length > PET_NAME_MAX_LENGTH) return { ok: false, error: 'name-too-long' }\n    this.ledger.setPetName(this.selectedPetId(), trimmed)\n    this.flush()\n    return { ok: true, name: trimmed }\n  }\n\n  /**\n   * Apply a committed settings section to the persisted selection and display\n   * config. Called by the settings surface on every change; values are\n   * clamped exactly like the setConfig RPC so both write paths converge.\n   * @param section - the resolved settings section.\n   */\n  applySettingsSection(section: PetSettingsSection): void {\n    this.decorationEnabled = section.decorationEnabled ?? true\n    this.statusBubbles = statusBubbleMode(section.statusBubbles)\n    const selected = typeof section.petId === 'string' ? this.registry.byId(section.petId) : undefined\n    if (selected !== undefined) {\n      this.ledger.setPetId(selected.id)\n      this.applyVoiceLayers(selected)\n    } else if (section.petId !== undefined) {\n      // The stored selection names a pet the registry no longer has: keep the\n      // current selection and repair the settings document.\n      this.syncSettingsFromPet()\n    }\n    const next = { ...this.ledger.snapshot.display }\n    // The pet's own hide/show intent, stored verbatim. The master switch is\n    // applied when the state view is produced (see the state view below), not\n    // here: writing the conjunction into pet.json turned `enabled: false` into\n    // a persisted \"the user hid the pet\" and the switch could never be undone -\n    // re-enabling it (or restarting) read that stored `false` straight back\n    // (#1762).\n    next.visible = section.visible\n    next.size = Math.round(Math.min(DISPLAY_SIZE_MAX, Math.max(DISPLAY_SIZE_MIN, section.size)))\n    next.right = Math.round(Math.min(DISPLAY_INSET_MAX, Math.max(0, section.right)))\n    next.bottom = Math.round(Math.min(DISPLAY_INSET_MAX, Math.max(0, section.bottom)))\n    next.bubbleScale = Math.min(BUBBLE_SCALE_MAX, Math.max(BUBBLE_SCALE_MIN, section.bubbleScale ?? next.bubbleScale))\n    this.ledger.setDisplay(next)\n    this.flush()\n  }\n\n  /** Mirror the persisted display config into the settings document (best-effort). */\n  private syncSettingsFromPet(): void {\n    const settings = this.ctx.get('settings', false) as { update(ns: string, patch: object): Promise<void> } | undefined\n    if (settings === undefined) return\n    const ns = this.settingsNamespaceProvider?.() ?? PET_SETTINGS_NAMESPACE\n    const snapshot = this.ledger.snapshot\n    void settings.update(ns, {\n      visible: snapshot.display.visible,\n      size: snapshot.display.size,\n      right: snapshot.display.right,\n      bottom: snapshot.display.bottom,\n      petId: snapshot.petId,\n    }).catch(() => {\n      // A settings write failure must not break the pet's own persistence.\n    })\n  }\n\n  /** Award the turn reward once per completed turn (idempotent per session + turn). */\n  private rewardTurn(sessionId: string, turn: number): void {\n    if (this.ledger.rewardTurn(sessionId, turn, Date.now())) this.flush()\n  }\n\n  /** Preserve turn rewards for installations that only emit legacy activity. */\n  private rewardLegacyTurn(): void {\n    if (this.ledger.rewardLegacyTurn(Date.now())) this.flush()\n  }\n\n  private view(currentSessionId?: string): PetStateView {\n    const snapshot = this.machine.render()\n    const entry = this.activeEntry()\n    // One bubble per concurrently active TOP-LEVEL session. The GUI's current\n    // session leads the stack when reported (the browser half passes its\n    // session list's 'current'); everything else keeps the most recent\n    // meaningful event order. Subagent children render no bubble of their own\n    // (their activity already shows through the spawning conversation's\n    // bubble/display, and the bubble buttons navigate to GUI sessions, which\n    // subagents are not). Sessions whose own machine has settled (no bubble\n    // copy) drop out, so a finished turn does not leave a stale bubble behind.\n    const sessions: PetSessionView[] = []\n    for (const [session, activity] of [...this.sessionActivity.entries()].reverse()) {\n      if (sessions.length >= MAX_SESSION_BUBBLES) break\n      if (session.header?.origin === 'subagent') continue\n      const perSession = activity.machine.render()\n      if (perSession.bubble === undefined) continue\n      // Each session's whisper rides its own bubble while fresh; an expired\n      // whisper simply stops appearing (the client's 2 s poll drops it).\n      const whisper = activity.whisper\n      const freshWhisper = whisper !== undefined && Date.now() - whisper.at < WHISPER_TTL_MS\n        ? whisper.text\n        : undefined\n      sessions.push({\n        sessionId: String(session.id),\n        animation: perSession.animation,\n        bubble: perSession.bubble,\n        phase: perSession.phase,\n        ...(freshWhisper === undefined ? {} : { whisper: freshWhisper }),\n      })\n    }\n    // The browser half reports the session the user is currently on; that\n    // session's bubble leads the stack (its whisper then speaks on the\n    // collapsed single bubble). An unreported or absent session keeps the\n    // legacy most-recent-first order.\n    if (currentSessionId !== undefined) {\n      const index = sessions.findIndex(session => session.sessionId === currentSessionId)\n      if (index > 0) sessions.unshift(sessions.splice(index, 1)[0]!)\n    }\n    const decoration = this.activeDecoration()\n    // Gameplay view: a read-only projection. The settle runs on a copy, so\n    // polling never writes pet.json (verbs settle and persist).\n    const gameplayDef = this.gameplayDef()\n    let gameplay: PetGameplayStateView | undefined\n    if (gameplayDef !== undefined) {\n      const { state } = this.gameplayState(gameplayDef, Date.now())\n      settleGameplay(state, gameplayDef, Date.now(), { sessionActive: snapshot.sessionActive })\n      gameplay = this.gameplayViewOf(state)\n    }\n    // Read-only: the ledger settles on economic events only, never on a read,\n    // so polling the state cannot trigger pet.json writes.\n    // One slot per publishing plugin (issue #1812); an expired entry simply\n    // stops appearing (the client's 2 s poll drops it), no timer owns removal.\n    const announcements = this.freshAnnouncements()\n    // The freshest entry keeps the pre-#1812 meaning of the singular field, so\n    // a browser half that predates the array still renders one bubble instead\n    // of none (a rolling upgrade must never blank a publisher's bubble).\n    const announcement = announcements.reduce<PetAnnouncement | undefined>(\n      (freshest, entry) => freshest === undefined || entry.at > freshest.at ? entry : freshest,\n      undefined,\n    )\n    const skin = this.persistedSkin(entry)\n    // The hover panel's action row extensions (issue #6). Served on every poll\n    // so a plugin that mounts or disposes its registration shows up (or goes\n    // away) within one tick, without a separate endpoint.\n    const panelActions = this.panelActions.views()\n    return {\n      animation: snapshot.animation,\n      ...(snapshot.bubble === undefined ? {} : { bubble: snapshot.bubble }),\n      phase: snapshot.phase,\n      sessionActive: snapshot.sessionActive,\n      sessions,\n      ...(decoration === undefined ? {} : { decoration }),\n      ...(announcement === undefined ? {} : { announcement }),\n      ...(announcements.length === 0 ? {} : { announcements }),\n      statusBubbles: this.statusBubbles,\n      ...(panelActions.length === 0 ? {} : { panelActions }),\n      affinity: this.ledger.affinityView(Date.now()),\n      // The one place the two visibility answers are combined: the pet's own\n      // hide/show intent AND the plugin master switch. Producing the effective\n      // value here - rather than storing it - keeps the switch reversible and\n      // keeps pet.json describing only what the user chose (#1762).\n      display: { ...this.ledger.snapshot.display, visible: this.isEnabled() && this.ledger.snapshot.display.visible },\n      pet: {\n        id: entry.id,\n        displayName: entry.displayName,\n        description: entry.description,\n      },\n      name: this.petName(),\n      ...(skin === undefined ? {} : { skin }),\n      treats: {\n        stocked: this.ledger.snapshot.treats.treats,\n        max: this.ledger.treatMax,\n      },\n      ...(gameplay === undefined ? {} : { gameplay }),\n    }\n  }\n\n  private flush(): void {\n    try {\n      savePetPersist(this.ledger.snapshot, this.persistDir)\n    } catch {\n      // Persistence is best-effort; the in-memory ledger keeps working.\n    }\n  }\n}\n"
    },
    {
      "path": "src/routes.ts",
      "content": "/**\n * Pet HTTP routes — the browser half talks to the host through plain\n * same-origin JSON endpoints ('/api/pet/*') and loads pet assets from\n * '/pet/<id>/*'. The '/plugins/' endpoint only serves client bundles and RPC\n * domains are platform-registered, so the pet serves its own API and media —\n * the same pattern as dsh-remote-web-ui's '/api/pair' family. The asset route\n * is one prefix registration serving every registry entry (manifest, atlas,\n * optional previews), so adding a pet never touches route wiring. Both the\n * JSON API, the asset prefix, and the Live2D runtime prefix are loopback-only\n * by default; a live paired-device cookie is an extra allow path when\n * remote-web-ui is loaded.\n * @module @linxin666/dsh-pet/routes\n */\n\nimport { existsSync, realpathSync, statSync } from 'node:fs'\nimport { readFile } from 'node:fs/promises'\nimport { join, sep } from 'node:path'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { WebRoute } from '@deepseek-ai/dsh-host-webserver'\nimport type { PetService } from './service.ts'\nimport type { PetInteraction } from './affinity.ts'\nimport { DECORATION_ASSET_PREFIX, petEntryView, petPackageRoot, type PetEntry, type PetRegistry } from './registry.ts'\nimport { isPetAllowed } from './access.ts'\nimport { dshHome } from './dsh-home.ts'\nimport { readJsonBody, writeJson } from './http.ts'\n\n/** Browser-facing base path of the pet API. */\nexport const PET_API_PREFIX = '/api/pet'\n\n/** Browser-facing base path of the pet asset routes ('/pet/<id>/...'). */\nexport const PET_ASSET_PREFIX = '/pet'\n\nconst MANIFEST_FILE = 'pet.json'\nconst PREVIEW_DIR = 'previews'\nconst PREVIEW_PATTERN = /^[A-Za-z0-9._-]+$/\n\n/**\n * Per-class size ceilings for served pet assets, in bytes (pet-center M2 P3,\n * issue #623). Constants are tested directly; makePetRoutes accepts an\n * override so tests can exercise the 413 path with tiny caps.\n */\nexport const PET_ASSET_CAPS = {\n  /** pet.json manifest. */\n  manifest: 64 * 1024,\n  /** Atlas, preview and Live2D texture imagery. */\n  image: 20 * 1024 * 1024,\n  /** Live2D model closure files (.moc3, motion/physics/expression JSON; M3). */\n  model: 32 * 1024 * 1024,\n} as const\n\n/** Size-cap profile the asset route enforces (test seam). */\nexport interface PetAssetCaps {\n  manifest: number\n  image: number\n  model: number\n}\n\n/** Imagery extensions classify into the image cap; everything else served from a closure is model-class. */\nconst IMAGE_EXTENSIONS: ReadonlySet<string> = new Set(['.webp', '.png', '.gif', '.jpg', '.jpeg'])\n\n/** Lowercased file extension ('' when none). */\nfunction extensionOf(file: string): string {\n  const dot = file.lastIndexOf('.')\n  return dot < 0 ? '' : file.slice(dot).toLowerCase()\n}\n\n/**\n * Realpaths of containment bases, resolved once per base instead of once per\n * request: every asset/runtime/decoration request used to pay a base\n * realpathSync on the hot path. Bases are registry entry directories and the\n * runtime roots — an immutable, registry-bounded set. Only successes are\n * cached (a missing base keeps failing per request), and a symlinked base\n * re-pointed mid-process fails containment until restart, which is the\n * deny-safe direction.\n */\nconst REAL_BASE_CACHE = new Map<string, string>()\n\n/**\n * realpath containment: resolve both sides and require the candidate to stay\n * inside the base directory. A pet directory (or an atlas/preview inside it)\n * that is a symlink escaping its root is rejected, never followed. The\n * candidate is realpath'ed live on every call; only the base side is cached.\n */\nexport function containedRealpath(base: string, candidate: string): string | undefined {\n  try {\n    let realBase = REAL_BASE_CACHE.get(base)\n    if (realBase === undefined) {\n      realBase = realpathSync(base)\n      REAL_BASE_CACHE.set(base, realBase)\n    }\n    const realCandidate = realpathSync(candidate)\n    return realCandidate === realBase || realCandidate.startsWith(realBase + sep)\n      ? realCandidate\n      : undefined\n  } catch {\n    return undefined\n  }\n}\n\nconst MIME_BY_EXT: Readonly<Record<string, string>> = {\n  '.webp': 'image/webp',\n  '.png': 'image/png',\n  '.gif': 'image/gif',\n  '.jpg': 'image/jpeg',\n  '.jpeg': 'image/jpeg',\n  '.json': 'application/json',\n}\n\n/** Content type by file extension (safe fallback: octet-stream). */\nfunction mimeFor(file: string): string {\n  const dot = file.lastIndexOf('.')\n  if (dot < 0) return 'application/octet-stream'\n  return MIME_BY_EXT[file.slice(dot).toLowerCase()] ?? 'application/octet-stream'\n}\n\n/** Weak validator from size + mtime, shared by the three file routes. */\nfunction weakEtag(stat: { size: number; mtimeMs: number }): string {\n  return '\"' + stat.size.toString(16) + '-' + Math.round(stat.mtimeMs).toString(16) + '\"'\n}\n\n/** Answer 304 when If-None-Match matches the etag; true when handled. */\nfunction revalidated(req: IncomingMessage, res: ServerResponse, etag: string): boolean {\n  if (req.headers['if-none-match'] !== etag) return false\n  res.writeHead(304, { etag, 'cache-control': 'no-cache' })\n  res.end()\n  return true\n}\n\n/** Require the method or answer 405. */\nfunction requireMethod(req: IncomingMessage, res: ServerResponse, method: string): boolean {\n  if (req.method === method) return true\n  writeJson(res, 405, { ok: false, error: 'method-not-allowed' })\n  return false\n}\n\n/** Shared route fence: loopback always passes; a live paired-device cookie is an extra allow path. */\nfunction guard(ctx: Context, req: IncomingMessage, res: ServerResponse): boolean {\n  if (isPetAllowed(ctx, req)) return true\n  writeJson(res, 403, { ok: false, error: 'forbidden: loopback-only' })\n  return false\n}\n\n/** Wrap one async service call as a GET JSON route (request passed through for query params). */\nfunction getRoute(ctx: Context, path: string, run: (req: IncomingMessage) => Promise<unknown>): WebRoute {\n  return {\n    kind: 'exact',\n    path,\n    handler: (req: IncomingMessage, res: ServerResponse): void => {\n      if (!guard(ctx, req, res)) return\n      if (!requireMethod(req, res, 'GET')) return\n      run(req).then((value) => writeJson(res, 200, value), (error) => {\n        writeJson(res, 500, { ok: false, error: error instanceof Error ? error.message : String(error) })\n      })\n    },\n  }\n}\n\n/** Wrap one async service call as a POST JSON route (body passed through). */\nfunction postRoute(ctx: Context, path: string, run: (body: Record<string, unknown>) => Promise<unknown>): WebRoute {\n  return {\n    kind: 'exact',\n    path,\n    handler: (req: IncomingMessage, res: ServerResponse): Promise<void> => {\n      if (!guard(ctx, req, res)) return Promise.resolve()\n      if (!requireMethod(req, res, 'POST')) return Promise.resolve()\n      // Shared lenient reader (64 KiB cap): an empty body yields null and is\n      // restored to {} at the call site (legacy empty-body semantics); invalid\n      // JSON and over-limit bodies also yield null, so the endpoint validators\n      // below keep answering 400 with the same { ok: false, error } envelope.\n      return readJsonBody(req, { maxBytes: 64 * 1024 }).then((parsed) => {\n        const payload = parsed ?? {}\n        const record = (typeof payload === 'object' && payload !== null) ? payload as Record<string, unknown> : {}\n        return run(record).then(\n          (value) => writeJson(res, 200, value),\n          (error) => {\n            writeJson(res, 400, { ok: false, error: error instanceof Error ? error.message : String(error) })\n          },\n        )\n      }, (error) => {\n        writeJson(res, 400, { ok: false, error: error instanceof Error ? error.message : String(error) })\n      })\n    },\n  }\n}\n\n/** Legacy URL aliases: each entry's directory basename (e.g. 'whale'). */\nfunction dirAliases(registry: PetRegistry): Map<string, PetEntry> {\n  const aliases = new Map<string, PetEntry>()\n  for (const entry of registry.entries) {\n    const alias = entry.dir.split(/[\\\\/]/).pop() ?? ''\n    if (alias !== '' && !aliases.has(alias)) aliases.set(alias, entry)\n  }\n  return aliases\n}\n\n/**\n * The one asset handler behind the '/pet' prefix. Resolves the pet by id (or\n * legacy directory alias), then serves exactly the files a manifest declares:\n * pet.json, the entry's servable set (the sprite2d atlas, or the live2d\n * model3.json plus its reference closure — pet-center M3), and optional\n * 'previews/<name>' media. The servable match is an exact string comparison\n * against scan-time normalized paths, so crafted '..' or '.' segments never\n * match; containedRealpath stays as the second layer. Composed pets without\n * a manifest file get a synthesized pet.json.\n */\nfunction assetHandler(ctx: Context, registry: PetRegistry, caps: PetAssetCaps): WebRoute['handler'] {\n  const aliases = dirAliases(registry)\n  // The servable match is a Set probe instead of a linear scan: a full live2d\n  // closure routinely exceeds a hundred files, each fetched through this\n  // handler per mount. The registry is an immutable snapshot, so the sets are\n  // built once per handler.\n  const servableById = new Map<string, ReadonlySet<string>>(\n    registry.entries.map(entry => [entry.id, new Set(entry.servable)]),\n  )\n  return ((req: IncomingMessage, res: ServerResponse) => {\n    if (!guard(ctx, req, res)) return\n    if (req.method !== 'GET' && req.method !== 'HEAD') {\n      res.writeHead(405)\n      res.end()\n      return\n    }\n    let pathname: string\n    try {\n      pathname = new URL(req.url ?? '/', 'http://pet.local').pathname\n    } catch {\n      res.writeHead(400)\n      res.end()\n      return\n    }\n    const segments = pathname.split('/').filter(segment => segment !== '')\n    if (segments[0] !== 'pet' || segments[1] === undefined) {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    let id: string\n    try {\n      id = decodeURIComponent(segments[1])\n    } catch {\n      res.writeHead(400)\n      res.end()\n      return\n    }\n    const entry = registry.byId(id) ?? aliases.get(id)\n    if (entry === undefined) {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    const rest: string[] = []\n    for (const segment of segments.slice(2)) {\n      let decoded: string\n      try {\n        decoded = decodeURIComponent(segment)\n      } catch {\n        res.writeHead(400)\n        res.end()\n        return\n      }\n      rest.push(decoded)\n    }\n    const rel = rest.join('/')\n    let file: string | undefined\n    let synthesized = false\n    if (rest.length === 1 && rest[0] === MANIFEST_FILE) {\n      const manifestFile = join(entry.dir, MANIFEST_FILE)\n      file = existsSync(manifestFile) ? manifestFile : undefined\n      if (file === undefined) synthesized = true\n    } else if (rest.length > 0 && servableById.get(entry.id)?.has(rel)) {\n      file = join(entry.dir, rel)\n    } else if (rest.length === 2 && rest[0] === PREVIEW_DIR && PREVIEW_PATTERN.test(rest[1]!)) {\n      const preview = join(entry.dir, PREVIEW_DIR, rest[1]!)\n      file = existsSync(preview) ? preview : undefined\n    }\n    if (synthesized) {\n      const body = Buffer.from(JSON.stringify(petEntryView(entry, registry.globalVoice), null, 2), 'utf8')\n      res.writeHead(200, {\n        'content-type': 'application/json; charset=utf-8',\n        'content-length': String(body.byteLength),\n        'cache-control': 'no-cache',\n      })\n      if (req.method === 'HEAD') {\n        res.end()\n        return\n      }\n      res.end(body)\n      return\n    }\n    if (file === undefined) {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    // realpath containment: a symlink escaping the pet directory is refused.\n    const resolved = containedRealpath(entry.dir, file)\n    if (resolved === undefined) {\n      res.writeHead(403)\n      res.end()\n      return\n    }\n    // Enforce the size ceiling before the file is read into memory.\n    const cap = rest.length === 1 && rest[0] === MANIFEST_FILE\n      ? caps.manifest\n      : IMAGE_EXTENSIONS.has(extensionOf(rel)) ? caps.image : caps.model\n    let stat: ReturnType<typeof statSync>\n    try {\n      stat = statSync(resolved)\n      if (stat.size > cap) {\n        res.writeHead(413)\n        res.end()\n        return\n      }\n    } catch {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    // 'no-cache' forces revalidation before every reuse, and the validator\n    // lets repeat requests settle as 304 — atlases and frames are the largest\n    // payloads the plugin serves (up to the 20 MB image cap), and without a\n    // validator every remount or page load would re-download them in full.\n    const etag = weakEtag(stat)\n    if (revalidated(req, res, etag)) return\n    return readFile(resolved).then((body) => {\n      res.writeHead(200, {\n        'content-type': mimeFor(resolved),\n        'content-length': String(body.byteLength),\n        'cache-control': 'no-cache',\n        etag,\n      })\n      if (req.method === 'HEAD') {\n        res.end()\n        return\n      }\n      res.end(body)\n    }, () => {\n      res.writeHead(404)\n      res.end()\n    })\n  }) as WebRoute['handler']\n}\n\n/** Browser-facing base path of the plugin runtime files (pet-center M3). */\nexport const PET_RUNTIME_PREFIX = PET_API_PREFIX + '/runtime'\n\n/**\n * The runtime files the route may serve, by exact name (no slashes, no\n * user-controlled path segments, so traversal is structurally impossible):\n * the user-supplied Cubism Core from the pet runtime directory (the plugin\n * never bundles or downloads it — issue #623 M1 §0) and the plugin-shipped\n * MIT vendor bundle from the package lib directory.\n */\nconst RUNTIME_FILES: Readonly<Record<string, { root: 'runtimeDir' | 'vendorDir' }>> = {\n  'live2dcubismcore.min.js': { root: 'runtimeDir' },\n  'live2d-vendor.js': { root: 'vendorDir' },\n  'live2d-vendor.js.map': { root: 'vendorDir' },\n}\n\n/** Size ceiling for one runtime file (the Cubism Core is ~200 KB today). */\nexport const PET_RUNTIME_CAP = 16 * 1024 * 1024\n\n/** Runtime file roots (test seam; defaults resolve from the environment). */\nexport interface PetRuntimeRoots {\n  /** User-supplied runtime directory (defaults to '$DSH_HOME/pets/.runtime'). */\n  runtimeDir?: string\n  /** Plugin vendor bundle directory (defaults to the package 'lib'). */\n  vendorDir?: string\n}\n\n/**\n * The runtime handler behind '/api/pet/runtime/<name>'. A missing file\n * answers 404 with a JSON marker the client renderer turns into install\n * guidance (the Cubism Core is user-supplied, so its absence is a normal\n * state, not an error).\n */\nfunction runtimeHandler(ctx: Context, roots: { runtimeDir: string; vendorDir: string }): WebRoute['handler'] {\n  return ((req: IncomingMessage, res: ServerResponse) => {\n    if (!guard(ctx, req, res)) return\n    if (req.method !== 'GET' && req.method !== 'HEAD') {\n      res.writeHead(405)\n      res.end()\n      return\n    }\n    let pathname: string\n    try {\n      pathname = new URL(req.url ?? '/', 'http://pet.local').pathname\n    } catch {\n      res.writeHead(400)\n      res.end()\n      return\n    }\n    const rest = pathname.slice(PET_RUNTIME_PREFIX.length).replace(/^\\/+/, '')\n    let name: string\n    try {\n      name = decodeURIComponent(rest)\n    } catch {\n      res.writeHead(400)\n      res.end()\n      return\n    }\n    const spec = RUNTIME_FILES[name]\n    // Exact-name allow-list: anything with a path separator never matches.\n    if (spec === undefined) {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    const base = spec.root === 'runtimeDir' ? roots.runtimeDir : roots.vendorDir\n    const file = join(base, name)\n    if (!existsSync(file)) {\n      writeJson(res, 404, { ok: false, error: 'runtime-file-missing', file: name })\n      return\n    }\n    const resolved = containedRealpath(base, file)\n    if (resolved === undefined) {\n      res.writeHead(403)\n      res.end()\n      return\n    }\n    let stat: ReturnType<typeof statSync>\n    try {\n      stat = statSync(resolved)\n      if (stat.size > PET_RUNTIME_CAP) {\n        res.writeHead(413)\n        res.end()\n        return\n      }\n    } catch {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    // Same validator as the asset routes: the Cubism Core and vendor bundle\n    // ride every page load of a live2d pet, so revalidation should settle as\n    // 304 instead of re-downloading the full bodies.\n    const etag = weakEtag(stat)\n    if (revalidated(req, res, etag)) return\n    return readFile(resolved).then((body) => {\n      res.writeHead(200, {\n        'content-type': name.endsWith('.map') ? 'application/json' : 'application/javascript; charset=utf-8',\n        'content-length': String(body.byteLength),\n        'cache-control': 'no-cache',\n        etag,\n      })\n      if (req.method === 'HEAD') {\n        res.end()\n        return\n      }\n      res.end(body)\n    }, () => {\n      res.writeHead(404)\n      res.end()\n    })\n  }) as WebRoute['handler']\n}\n\n/**\n * The decoration asset handler behind '/api/pet/decoration/<id>/<file>'\n * (pet-center M5, #567). Serves exactly the files a decoration descriptor\n * declares — decoration.json and the PNG/WebP strip — by exact allow-list\n * match, with realpath containment and the same size ceilings as pet\n * assets. Crafted '..' or '.' segments never match the normalized closure.\n */\nfunction decorationHandler(ctx: Context, registry: PetRegistry, caps: PetAssetCaps): WebRoute['handler'] {\n  return (req: IncomingMessage, res: ServerResponse): void => {\n    if (!guard(ctx, req, res)) return\n    if (req.method !== 'GET' && req.method !== 'HEAD') {\n      res.writeHead(405)\n      res.end()\n      return\n    }\n    let pathname: string\n    try {\n      pathname = new URL(req.url ?? '/', 'http://pet.local').pathname\n    } catch {\n      res.writeHead(400)\n      res.end()\n      return\n    }\n    const segments = pathname.split('/').filter(segment => segment !== '')\n    const prefixSegments = DECORATION_ASSET_PREFIX.split('/').filter(segment => segment !== '')\n    if (segments.length < prefixSegments.length + 2) {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    for (let i = 0; i < prefixSegments.length; i += 1) {\n      if (segments[i] !== prefixSegments[i]) {\n        res.writeHead(404)\n        res.end()\n        return\n      }\n    }\n    let id: string\n    try {\n      id = decodeURIComponent(segments[prefixSegments.length])\n    } catch {\n      res.writeHead(400)\n      res.end()\n      return\n    }\n    const entry = registry.decorationById?.(id)\n    if (entry === undefined) {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    const rest: string[] = []\n    for (const segment of segments.slice(prefixSegments.length + 1)) {\n      let decoded: string\n      try {\n        decoded = decodeURIComponent(segment)\n      } catch {\n        res.writeHead(400)\n        res.end()\n        return\n      }\n      rest.push(decoded)\n    }\n    const rel = rest.join('/')\n    if (!entry.servable.includes(rel)) {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    const file = join(entry.dir, rel)\n    const resolved = containedRealpath(entry.dir, file)\n    if (resolved === undefined) {\n      res.writeHead(403)\n      res.end()\n      return\n    }\n    const cap = rel === 'decoration.json' ? caps.manifest : caps.image\n    let stat: ReturnType<typeof statSync>\n    try {\n      stat = statSync(resolved)\n      if (stat.size > cap) {\n        res.writeHead(413)\n        res.end()\n        return\n      }\n    } catch {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    // Weak ETag from size + mtime: 'no-cache' forces revalidation, and the\n    // validator lets repeat requests settle as 304 — the ornament remounts\n    // on whisper and display-session flips, and without a validator each\n    // remount would re-download the full strip body.\n    const etag = weakEtag(stat)\n    if (revalidated(req, res, etag)) return\n    readFile(resolved).then((body) => {\n      res.writeHead(200, {\n        'content-type': mimeFor(resolved),\n        'content-length': String(body.byteLength),\n        'cache-control': 'no-cache',\n        etag,\n      })\n      if (req.method === 'HEAD') {\n        res.end()\n        return\n      }\n      res.end(body)\n    }, () => {\n      res.writeHead(404)\n      res.end()\n    })\n  }\n}\n\n/** Build the full route family (API + assets + runtime) for one service. */\nexport function makePetRoutes(deps: { service: PetService; ctx: Context; assetCaps?: PetAssetCaps } & PetRuntimeRoots): WebRoute[] {\n  const { service, ctx } = deps\n  const apiRoutes: WebRoute[] = [\n    getRoute(ctx, PET_API_PREFIX + '/state', (req) => {\n      // The browser half reports the GUI's current session id so the bubble\n      // stack can lead with the session the user is actually looking at.\n      const current = new URL(req.url ?? '/', 'http://pet.local').searchParams.get('current')\n      return service.state(current === null || current === '' ? undefined : current)\n    }),\n    getRoute(ctx, PET_API_PREFIX + '/pets', () => service.pets()),\n    getRoute(ctx, PET_API_PREFIX + '/diagnostics', () => service.diagnostics()),\n    postRoute(ctx, PET_API_PREFIX + '/interact', (body) => {\n      const kind = body.kind as PetInteraction | undefined\n      if (kind !== 'pet' && kind !== 'feed') return Promise.reject(new Error('invalid-kind'))\n      return service.interact(kind)\n    }),\n    postRoute(ctx, PET_API_PREFIX + '/set-visible', (body) => {\n      const visible = body.visible\n      if (typeof visible !== 'boolean') return Promise.reject(new Error('invalid-visible'))\n      return service.setVisible(visible)\n    }),\n    postRoute(ctx, PET_API_PREFIX + '/set-config', (body) => service.setConfig({\n      ...(typeof body.size === 'number' ? { size: body.size } : {}),\n      ...(typeof body.right === 'number' ? { right: body.right } : {}),\n      ...(typeof body.bottom === 'number' ? { bottom: body.bottom } : {}),\n      ...(typeof body.visible === 'boolean' ? { visible: body.visible } : {}),\n    })),\n    postRoute(ctx, PET_API_PREFIX + '/set-name', (body) => {\n      const name = body.name\n      if (typeof name !== 'string') return Promise.reject(new Error('invalid-name'))\n      return service.setName(name)\n    }),\n    postRoute(ctx, PET_API_PREFIX + '/set-skin', (body) => {\n      const skin = body.skin\n      if (skin !== undefined && typeof skin !== 'string') return Promise.reject(new Error('invalid-skin'))\n      return service.setSkin(skin === undefined || skin === '' ? undefined : skin)\n    }),\n    postRoute(ctx, PET_API_PREFIX + '/set-pet', (body) => {\n      const petId = body.petId\n      if (typeof petId !== 'string') return Promise.reject(new Error('invalid-pet'))\n      return service.setPetId(petId)\n    }),\n    // Hover-panel action click (issue #6): the browser half owns no plugin\n    // callbacks, so a click on a registered action travels back here and the\n    // service dispatches it to the plugin that registered it. Same loopback /\n    // paired-device guard as every other endpoint in this family.\n    postRoute(ctx, PET_API_PREFIX + '/panel-action', (body) => {\n      const id = body.id\n      if (typeof id !== 'string') return Promise.reject(new Error('invalid-panel-action'))\n      return service.selectPanelAction(id)\n    }),\n    // Gameplay verbs (miku-pet generalization): touch rolls a named zone's\n    // branch; the omitted-zone form is the plain-click boost during a touch\n    // animation. Mode/tick/buy drive the work, sleep and shop loops.\n    postRoute(ctx, PET_API_PREFIX + '/gameplay/touch', (body) => {\n      const zone = body.zone\n      if (zone !== undefined && typeof zone !== 'string') return Promise.reject(new Error('invalid-zone'))\n      return service.gameplayTouch(zone)\n    }),\n    postRoute(ctx, PET_API_PREFIX + '/gameplay/mode', (body) => {\n      const mode = body.mode\n      // The id is checked against the pet's own mode set in the service (work,\n      // sleep, or any declared 'modes' entry).\n      if (mode !== null && typeof mode !== 'string') return Promise.reject(new Error('invalid-mode'))\n      return service.gameplaySetMode(mode)\n    }),\n    postRoute(ctx, PET_API_PREFIX + '/gameplay/work-tick', () => service.gameplayWorkTick()),\n    postRoute(ctx, PET_API_PREFIX + '/gameplay/buy', (body) => {\n      const item = body.item\n      if (typeof item !== 'string') return Promise.reject(new Error('invalid-item'))\n      return service.gameplayBuy(item)\n    }),\n  ]\n\n  const assetRoute: WebRoute = {\n    kind: 'prefix',\n    path: PET_ASSET_PREFIX,\n    handler: assetHandler(ctx, service.registrySnapshot(), deps.assetCaps ?? PET_ASSET_CAPS),\n  }\n\n  const runtimeRoute: WebRoute = {\n    kind: 'prefix',\n    path: PET_RUNTIME_PREFIX,\n    handler: runtimeHandler(ctx, {\n      runtimeDir: deps.runtimeDir ?? join(dshHome(), 'pets', '.runtime'),\n      vendorDir: deps.vendorDir ?? join(petPackageRoot(import.meta.url), 'lib'),\n    }),\n  }\n\n  const decorationRoute: WebRoute = {\n    kind: 'prefix',\n    path: DECORATION_ASSET_PREFIX,\n    handler: decorationHandler(ctx, service.registrySnapshot(), deps.assetCaps ?? PET_ASSET_CAPS),\n  }\n\n  return [...apiRoutes, assetRoute, runtimeRoute, decorationRoute]\n}\n\n// Re-exported for the package surface (the registry owns the definition now).\nexport { petPackageRoot } from './registry.ts'\n"
    },
    {
      "path": "src/index.ts",
      "content": "/**\n * dsh-pet host half — mounts the pet service and its HTTP routes. The\n * browser half (the './client' entry) renders the selected pet and drives it\n * through the same-origin '/api/pet/*' JSON endpoints plus the '/pet/<id>/*'\n * media route. The host builds the multi-pet registry once at startup from\n * the package assets, the hatch-pet custom pets directory, and composed\n * config entries; adding a pet means dropping a manifest + atlas into one of\n * those sources, never touching host or client code. Install via\n * 'dsh plugin --profile web add link:<dsh-web>/packages/dsh-pet'; the\n * cordis.patch.yml inserts this plugin row.\n * @module @linxin666/dsh-pet\n */\n\nimport { Context, type Volatile } from '@deepseek-ai/cordis'\n// Type-only: pulls the settings service's Context merge (ctx.settings).\nimport type {} from '@deepseek-ai/dsh-settings'\nimport type {} from '@deepseek-ai/dsh-host-webserver'\nimport z from '@deepseek-ai/schemastery'\nimport { DEFAULT_STATUS_BUBBLE_MODE, PET_SETTINGS_NAMESPACE, PetService, STATUS_BUBBLE_MODES, statusBubbleMode, type PetConfig, type PetSettingsSection, type PetStatusBubbleMode } from './service.ts'\nimport { makePetRoutes } from './routes.ts'\nimport { loadPetRegistry, petPackageRoot } from './registry.ts'\nimport { BUBBLE_SCALE_MAX, BUBBLE_SCALE_MIN, DEFAULT_PET_ID, DISPLAY_INSET_MAX, DISPLAY_SIZE_MAX, DISPLAY_SIZE_MIN, type PetDisplayConfig } from './persist.ts'\nimport { mountOnce } from './mount-once.ts'\n\nexport { PetService, MAX_SESSION_BUBBLES, DEFAULT_STATUS_BUBBLE_MODE, STATUS_BUBBLE_MODES, statusBubbleMode } from './service.ts'\nexport type {\n  PetConfig,\n  PetInteractResult,\n  PetSettingsSection,\n  PetSessionView,\n  PetStateView,\n  PetStatusBubbleMode,\n} from './service.ts'\nexport { MAX_PANEL_ACTIONS, PanelActionRegistry, normalizePanelAction } from './panel-actions.ts'\nexport type {\n  PetPanelActionContext,\n  PetPanelActionHandler,\n  PetPanelActionRegistration,\n  PetPanelActionView,\n} from './panel-actions.ts'\nexport {\n  AFFINITY_MAX,\n  AFFINITY_RANKS,\n  applyInteraction,\n  applyTurnReward,\n  emptyAffinity,\n  rankOf,\n} from './affinity.ts'\nexport type {\n  AffinityConfig,\n  AffinityRank,\n  AffinityRankName,\n  AffinityState,\n  InteractionOutcome,\n  PetInteraction,\n} from './affinity.ts'\nexport {\n  animationForPhase,\n  PetStateMachine,\n  rowOf,\n} from './state.ts'\nexport type {\n  ActivityPhase,\n  PetAnimation,\n  PetStateConfig,\n  PetStateInput,\n  PetStateSnapshot,\n} from './state.ts'\nexport {\n  consumeTreat,\n  defaultTreatConfig,\n  emptyTreatLedger,\n  settleTreatGrants,\n} from './treats.ts'\nexport type { TreatConfig, TreatLedger, TreatSettlement } from './treats.ts'\nexport {\n  BUILTIN_REMARKS,\n  REMARK_KINDS,\n  REMARK_LINE_MAX,\n  REMARK_LINES_MAX,\n  RemarkPicker,\n  builtinRemark,\n  normalizePetRemarks,\n} from './remarks.ts'\nexport type { PetRemarks, PetRemarksManifest, RemarkKind } from './remarks.ts'\nexport {\n  DEFAULT_PET_ID,\n  DEFAULT_PET_NAME,\n  PET_NAME_MAX_LENGTH,\n  defaultDisplayConfig,\n  emptyPersist,\n  loadPetPersist,\n  petHomeDir,\n  savePetPersist,\n} from './persist.ts'\nexport type { PetDisplayConfig, PetPersist } from './persist.ts'\nexport {\n  DEFAULT_FRAME_COUNTS,\n  DEFAULT_PET_CELL,\n  DEFAULT_PET_COLUMNS,\n  DEFAULT_PET_ROW_COUNT,\n  DEFAULT_TRACK_PATTERNS,\n  PET_ROW_ORDER,\n  codexPetsDir,\n  loadPetRegistry,\n  petEntryView,\n  petPackageRoot,\n  resolvePetManifest,\n} from './registry.ts'\nexport type {\n  PetDefinition,\n  PetEntry,\n  PetManifest,\n  PetRegistry,\n  PetRegistryOptions,\n  PetTrackDef,\n  PetTrackOverride,\n} from './registry.ts'\n\nexport {\n  makePetRoutes,\n  PET_API_PREFIX,\n  PET_ASSET_PREFIX,\n} from './routes.ts'\n\n/** Stable cordis plugin name (matches cordis.patch.yml insert id). */\nexport const name = 'pet'\n\n/** Services required before the pet can mount its surfaces. */\nexport const inject = ['webServer']\n\n/**\n * Defaults of the fields the pet's settings page edits. They are the schema\n * defaults of the pet row's own config, i.e. what a field the profile entry\n * never set resolves to.\n */\nexport const PET_FORM_DEFAULTS = {\n  visible: true,\n  size: 160,\n  right: 24,\n  bottom: 20,\n  bubbleScale: 1,\n  petId: DEFAULT_PET_ID,\n  enabled: true,\n  decorationEnabled: true,\n  statusBubbles: DEFAULT_STATUS_BUBBLE_MODE,\n} as const\n\n/**\n * One settings field as the config carries it. The Host commits an edit into\n * the running config through a live reference rather than remounting the row,\n * so a field usually arrives as that reference; a plain value appears when the\n * plugin runs outside a Loader (tests, direct mounts).\n */\nexport type LiveField<T> = Volatile<T> | T\n\n/** The pet's settings fields, as a profile entry's config declares them. */\nexport interface PetFormConfig {\n  /** Master switch for the plugin (browser half + host routes). */\n  enabled?: LiveField<boolean>\n  /** Status-decoration master switch (pet-center M5, #567); defaults to on. */\n  decorationEnabled?: LiveField<boolean>\n  /**\n   * Whether the pet renders its own session/status bubbles (issue #6);\n   * defaults to 'auto', which is exactly the behavior that shipped before\n   * the switch existed.\n   */\n  statusBubbles?: LiveField<PetStatusBubbleMode | undefined>\n  /** Master switch for the pet surface. */\n  visible?: LiveField<boolean>\n  /** Scale of the rendered pet in px (sprite cell height). */\n  size?: LiveField<number>\n  /** Horizontal inset from the viewport right edge, px. */\n  right?: LiveField<number>\n  /** Vertical inset from the viewport bottom edge, px. */\n  bottom?: LiveField<number>\n  /** Bubble typography multiplier on the automatic size following (#1549). */\n  bubbleScale?: LiveField<number>\n  /** Selected pet id (a registry entry; the service clamps stale values). */\n  petId?: LiveField<string | undefined>\n}\n\n/**\n * Plugin configuration. Under the 0.1.7 settings model a plugin's own Cordis\n * Config IS its settings page: the Host derives one form per profile entry\n * from this schema, so the fields the pet card edits live here with the\n * defaults the card inherits, next to the tuning block a profile may still\n * declare.\n *\n * Every page field is `volatile()` on purpose. The Host serves exactly the\n * volatile fields of a Config and refuses writes to any other path, and a\n * volatile field is the one it can commit into the RUNNING config: the pet\n * reads the edited value from the live reference instead of being remounted\n * for each edit (see `syncSettings` in `apply`). petId stays a plain string\n * because the service clamps the value against the registry, so a stored\n * selection naming a removed pet cannot invalidate the entry.\n */\nexport const Config = z.object({\n  visible: z.boolean().default(PET_FORM_DEFAULTS.visible).volatile(),\n  size: z.number().step(1).min(DISPLAY_SIZE_MIN).max(DISPLAY_SIZE_MAX).default(PET_FORM_DEFAULTS.size).volatile(),\n  right: z.number().step(1).min(0).max(DISPLAY_INSET_MAX).default(PET_FORM_DEFAULTS.right).volatile(),\n  bottom: z.number().step(1).min(0).max(DISPLAY_INSET_MAX).default(PET_FORM_DEFAULTS.bottom).volatile(),\n  bubbleScale: z.number().step(0.05).min(BUBBLE_SCALE_MIN).max(BUBBLE_SCALE_MAX).default(PET_FORM_DEFAULTS.bubbleScale).volatile(),\n  // An absent profile choice must leave the selection persisted in pet.json\n  // intact across restarts (aggregate rows have no served Host pet form).\n  petId: z.string().volatile(),\n  enabled: z.boolean().default(PET_FORM_DEFAULTS.enabled).volatile(),\n  decorationEnabled: z.boolean().default(PET_FORM_DEFAULTS.decorationEnabled).volatile(),\n  // The pet's own session/status bubbles (issue #6). 'auto' is the shipped\n  // behavior; 'off' is the opt-in a user (or a plugin that drives its own\n  // bubble surface) needs, and it hides ONLY those bubbles — the sprite, the\n  // interaction feedback and a sibling plugin's announcement bubble stay.\n  statusBubbles: z.union([...STATUS_BUBBLE_MODES]).default(PET_FORM_DEFAULTS.statusBubbles).volatile(),\n})\n\n/**\n * Read one live config field.\n * @param field - the field's live reference, plain value, or nothing at all.\n * @param fallback - value used when the field is absent.\n * @returns the current field value.\n */\nfunction readLive<T>(field: LiveField<T> | undefined, fallback: T): T {\n  if (field === undefined) return fallback\n  const ref = field as { get?: () => T | undefined }\n  return typeof ref.get === 'function' ? ref.get() ?? fallback : field as T\n}\n\n/**\n * Resolve one display field of the section. The precedence is deliberate:\n *\n * 1. an explicit profile value (`committed`) — the user's own choice, and the\n *    only signal that carries a value equal to the schema default on purpose;\n * 2. a live value the row committed at runtime, i.e. one that differs from the\n *    schema default, which is all an untouched field ever resolves to;\n * 3. what the pet's own `pet.json` already holds (`persisted`), so a field the\n *    profile never touched keeps the position the user dragged instead of\n *    snapping back to the schema default on the next mount.\n *\n * Step 3 is what makes a drag survive a restart. The display fields carry\n * schema defaults (`right: 24`, `bottom: 20` — the bottom-right corner), and a\n * config that never set them reads back exactly like one that set them to the\n * defaults, so without `persisted` the startup section resets the layout every\n * time the profile commits none — which is what an aggregate install does.\n * @param key - the display field to resolve.\n * @param live - the row config's own field, absent when the entry declares none.\n * @param persisted - the display the pet already shows (its own `pet.json`).\n * @param committed - the profile layer's explicit display values, when known.\n * @returns the value the pet runs with.\n */\nfunction displayField<K extends keyof PetDisplayConfig>(\n  key: K,\n  live: LiveField<PetDisplayConfig[K]> | undefined,\n  persisted: Partial<PetDisplayConfig>,\n  committed: Partial<PetDisplayConfig>,\n): PetDisplayConfig[K] {\n  const explicit = committed[key]\n  if (explicit !== undefined) return explicit\n  const value = readLive<PetDisplayConfig[K]>(live, PET_FORM_DEFAULTS[key])\n  if (value !== PET_FORM_DEFAULTS[key]) return value\n  const kept = persisted[key]\n  return kept === undefined ? value : kept\n}\n\n/**\n * The settings section the pet runs with: the effective values of the row's\n * own config. `fallbackPetId` covers a mount whose config names no pet at all\n * (a direct mount outside a Loader) — under a Loader the schema default is\n * always present, so the persisted selection stands whenever the config\n * carries it. `persisted` and `committed` give the display fields the same\n * treatment; see {@link displayField}.\n * @param config - the effective config of the pet row.\n * @param fallbackPetId - pet id to use when the config names none.\n * @param persisted - the display the pet already shows (its own `pet.json`).\n * @param committed - the profile layer's explicit display values, when known.\n * @returns the resolved settings section.\n */\nexport function petSettingsSection(\n  config: PetFormConfig,\n  fallbackPetId: string,\n  persisted: Partial<PetDisplayConfig> = {},\n  committed: Partial<PetDisplayConfig> = {},\n): PetSettingsSection {\n  // `visible` and `enabled` answer two DIFFERENT questions and are kept\n  // apart on purpose (#1762):\n  //\n  // - `visible` is the pet's own hide/show intent, persisted in its pet.json\n  //   and written by the sprite's hide/summon control and by the aggregate\n  //   shell's fallback switch.\n  // - `enabled` is the plugin master switch, which hides the pet whatever that\n  //   own intent says.\n  //\n  // The effective \"is it on screen\" state is the conjunction, and it belongs at\n  // the single point that PRODUCES the view (see PetService.state), never here\n  // and never written back to pet.json. Folding it into this field is what made\n  // the master switch one-way: switching it off stored the derived `false` as\n  // the user's own intent, so switching it on again (or restarting) read that\n  // stored `false` back and the pet never returned.\n  const enabled = readLive(config.enabled, PET_FORM_DEFAULTS.enabled)\n  return {\n    visible: displayField('visible', config.visible, persisted, committed),\n    size: displayField('size', config.size, persisted, committed),\n    right: displayField('right', config.right, persisted, committed),\n    bottom: displayField('bottom', config.bottom, persisted, committed),\n    bubbleScale: displayField('bubbleScale', config.bubbleScale, persisted, committed),\n    petId: readLive(config.petId, fallbackPetId),\n    enabled,\n    decorationEnabled: readLive(config.decorationEnabled, PET_FORM_DEFAULTS.decorationEnabled),\n    // Not a display field: the bubble switch has no persisted pet.json twin\n    // (it is a plugin-level rendering preference, like `decorationEnabled`),\n    // so it reads the live value directly and normalizes anything unknown to\n    // the shipped default instead of trusting the document.\n    statusBubbles: statusBubbleMode(readLive<PetStatusBubbleMode | undefined>(config.statusBubbles, undefined)),\n  }\n}\n\n/** The settings row ids a pet install is served under, most specific first. */\nconst PET_SETTINGS_ROW_IDS: readonly string[] = ['web-ui-pet', 'ui-pet', PET_SETTINGS_NAMESPACE]\n\n/**\n * The fields this host half reads off one settings descriptor. The settings\n * service serves one descriptor per plugin row (see `describe`), and a plugin's\n * own config IS its settings page, so the two that matter here are the row's\n * namespace and the profile layer's explicit values.\n */\ninterface ServedSettingsRow {\n  /** The profile entry's id, which is also this plugin's settings namespace. */\n  ns: string\n  /** The profile layer's explicit values; absent fields were never committed. */\n  user?: Partial<PetDisplayConfig>\n}\n\n/**\n * The settings row serving this plugin's own config, or undefined when the\n * settings service is not mounted (a direct mount) or serves no row for the pet.\n *\n * Every settings write has to address this row's id, and that id is not the\n * package's plugin name: an aggregate bundle renames child rows (`pet` becomes\n * `web-ui-pet`). The browser half resolves the same id through its own\n * `servedEntryId`, so both halves write to one namespace.\n * @param ctx - the plugin's context.\n * @returns the serving row, when there is one.\n */\nfunction servedRow(ctx: Context): ServedSettingsRow | undefined {\n  try {\n    const settings = ctx.get('settings', false) as { describe(): readonly ServedSettingsRow[] } | undefined\n    if (settings === undefined) return undefined\n    const rows = settings.describe()\n    for (const id of PET_SETTINGS_ROW_IDS) {\n      const row = rows.find(candidate => candidate.ns === id)\n      if (row !== undefined) return row\n    }\n    return undefined\n  } catch {\n    return undefined\n  }\n}\n\n/** Register the pet service and its API + asset routes on the context. */\nexport const apply = mountOnce('@linxin666/dsh-pet', applyImpl)\n\n/** Plugin config: the tuning block a profile may declare plus the pet's settings fields. */\nexport type PetPluginConfig = Omit<PetConfig, 'enabled' | 'decorationEnabled'> & PetFormConfig\n\nfunction applyImpl(ctx: Context, config: PetPluginConfig = {}): void {\n  const registry = config.registry\n    ?? loadPetRegistry({\n      packageRoot: petPackageRoot(import.meta.url),\n      ...(config.pets === undefined ? {} : { extra: config.pets }),\n    })\n  const service = new PetService(ctx, {\n    ...config,\n    enabled: readLive(config.enabled, PET_FORM_DEFAULTS.enabled),\n    decorationEnabled: readLive(config.decorationEnabled, PET_FORM_DEFAULTS.decorationEnabled),\n    statusBubbles: statusBubbleMode(readLive<PetStatusBubbleMode | undefined>(config.statusBubbles, undefined)),\n    registry,\n  })\n  // The mirror back into the settings document (see syncSettingsFromPet) has to\n  // address the row that serves this plugin's config, which an aggregate bundle\n  // renames; the id is resolved lazily, once the composition serves it.\n  service.settingsNamespaceProvider = () => servedRow(ctx)?.ns\n\n  // The effective settings ARE this row's own config: the Host serves one form\n  // per profile entry from `Config` above, and every edit is committed into the\n  // running config, so the plugin re-reads the section here instead of holding\n  // a separate settings document (0.1.6 registered one through\n  // settings.installSection/register and re-resolved it on every change). The\n  // display fields additionally read the persisted layout and the profile layer,\n  // so a mount with a config that never set them cannot reset a dragged\n  // position to the schema defaults (see displayField).\n  const current = (): PetSettingsSection =>\n    petSettingsSection(config, service.selectedPetId(), service.display(), servedRow(ctx)?.user)\n  // The browser half talks to the pet through same-origin JSON endpoints and\n  // loads each pet's atlas from the registry's own media route (RPC domains\n  // are platform-registered, so the pet serves its own API — the same\n  // pattern as dsh-remote-web-ui's /api/pair family). The routes are\n  // registered while the plugin is enabled; toggling the setting off makes\n  // the pet API disappear until it is re-enabled.\n  const routes = makePetRoutes({ service, ctx })\n  let disposeRoutes: (() => void) | undefined\n  const syncRoutes = (): void => {\n    const enabled = current().enabled ?? true\n    if (disposeRoutes === undefined && enabled) {\n      disposeRoutes = ctx.effect(\n        () => {\n          const disposers = routes.map((route) => ctx.webServer.register(route))\n          return () => { for (const dispose of disposers) dispose() }\n        },\n        'pet: routes',\n      )\n    } else if (disposeRoutes !== undefined && !enabled) {\n      disposeRoutes()\n      disposeRoutes = undefined\n    }\n  }\n  // Apply the row's config to the running service: pet.json mirrors the live\n  // display the drag / hide / summon interactions write (see\n  // syncSettingsFromPet), so a section the settings surface never touched\n  // resolves back to exactly what the pet already shows (the composition\n  // 'base' of the pre-0.1.7 section).\n  const syncSettings = (): void => {\n    const section = current()\n    service.applySettingsSection(section)\n    service.setEnabled(section.enabled ?? true)\n    syncRoutes()\n  }\n  // A settings edit lands in this row's live config reference and is announced\n  // here; the entry is NOT remounted for it, so the pet applies the new section\n  // itself (the pre-0.1.7 host ran the section's onChange hook for this).\n  ctx.on('loader/volatile-update', () => { syncSettings() })\n  ctx.inject(['settings'], (settingsCtx) => {\n    // The pet ships its own settings card (the browser half's\n    // 'settings.section' page), so the Host must not also generate a page for\n    // this entry from Config.\n    settingsCtx.effect(() => {\n      try {\n        return settingsCtx.settings.configure({ auto: false }, ctx.fiber)\n      } catch {\n        return () => {}\n      }\n    }, 'pet: settings page policy')\n  })\n  syncSettings()\n}\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Events {\n    /**\n     * Volatile config values were committed into the running fiber without a\n     * remount; dispatched to the owning fiber only. Declared by the Loader and\n     * restated here because this package carries no dependency on its types.\n     */\n    'loader/volatile-update'(paths: readonly (readonly string[])[]): void\n  }\n}\n"
    },
    {
      "path": "src/client/index.ts",
      "content": "/**\n * dsh-pet browser half — mounts the selected pet as a global floating\n * surface and drives it from the host's same-origin '/api/pet/*' JSON\n * endpoints: fetch the registry list once, poll the host snapshot (~2 s),\n * forward interactions, persist drag positions. The pet is host-global (no\n * session dimension), so it mounts directly onto 'document.body' via a\n * single React root — the [data-dsh-plugin=\"pet\"] container — rather than a\n * session-scoped slot: on the new-conversation screen no session exists, and\n * a dock-mounted pet would vanish there (issue #48). The sprite chrome\n * portals into that same root, so the root owns the whole surface and a\n * root-keyed suppressor can hide it as one unit. When the pet is hidden the\n * entry becomes a fixed-position summon button.\n * @module @linxin666/dsh-pet/client\n */\n\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport type { ISessions } from '@deepseek-ai/dsh-api-session-controller/client'\nimport type { SessionId } from '@deepseek-ai/dsh-api-remotes/client'\nimport type { ConfigForm, ConfigFormSnapshot } from '@deepseek-ai/dsh-client-ui-settings/client'\n// Type-only: pulls the locale plugin's Context merge (ctx.locale).\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\n// Type-only: pulls the shared configuration forms Context merge (ctx.configForms).\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-slots'\n// Type-only: pulls the ctx.slots merge (the renderer owns the slot registry since 0.1.2).\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-conversation/client'\n// Type-only: pulls the workspace plugin's Context merge (ctx.uiWorkspace), the\n// multi-instance navigation face that replaced ISessions.open().\nimport type {} from '@deepseek-ai/dsh-client-ui-workspace/client'\nimport type { PetDisplayConfig } from '../persist.ts'\nimport type { PetGameplayVerbResult, PetInteractResult, PetStateView } from '../service.ts'\nimport type { PetInteraction } from '../affinity.ts'\nimport type { PetDefinition } from '../registry.ts'\nimport { createElement } from 'react'\nimport { createRoot } from 'react-dom/client'\nimport { createPetStore, type PetStoreInstance } from './pet-store.ts'\nimport { createWorkTickGate } from './work-tick-gate.ts'\nimport { PetDockEntry, type PetInjected } from './PetDockEntry.tsx'\nimport { defaultPetRendererRegistry } from './renderers/registry.ts'\nimport { live2dRenderer } from './renderers/live2d.ts'\nimport { frames2dRenderer } from './renderers/frames2d.ts'\nimport { registerPetUiTeardown, takeoverPetUiTeardown } from './ui-teardown.ts'\nimport { PetSettingsCardController, type PetSettings } from './PetSettingsCard.tsx'\nimport { installPetSettingsRegistration } from './settings-registration.ts'\nimport { NS, en, zh } from './locales.ts'\nimport { mainViewSessionId } from './main-session.ts'\nimport { reportDailyHeartbeat } from './telemetry.ts'\n\n/** The host pet API as the browser sees it (same-origin JSON endpoints). */\ninterface PetHttpApi {\n  /** Poll the host snapshot; the GUI's current session id rides the query. */\n  state(currentSessionId?: string): Promise<PetStateView>\n  pets(): Promise<PetDefinition[]>\n  interact(kind: PetInteraction): Promise<PetInteractResult>\n  setVisible(visible: boolean): Promise<{ ok: true; display: PetDisplayConfig }>\n  setConfig(patch: Partial<PetDisplayConfig>): Promise<{ ok: true; display: PetDisplayConfig }>\n  setName(name: string): Promise<{ ok: true; name: string } | { ok: false; error: string }>\n  setPet(petId: string): Promise<{ ok: true; petId: string } | { ok: false; error: string }>\n  panelAction(id: string): Promise<{ ok: boolean; error?: string }>\n  setSkin(skin?: string): Promise<{ ok: boolean; error?: string; skin?: string }>\n  gameplayTouch(zone?: string): Promise<PetGameplayVerbResult>\n  gameplaySetMode(mode: string | null): Promise<PetGameplayVerbResult>\n  gameplayWorkTick(): Promise<PetGameplayVerbResult>\n  gameplayBuy(item: string): Promise<PetGameplayVerbResult>\n}\n\n/** Same-origin JSON fetch helper (GET without body, POST with JSON body). */\nasync function petFetch<T>(path: string, body?: unknown): Promise<T> {\n  const response = await fetch(path, body === undefined\n    ? {}\n    : {\n        method: 'POST',\n        headers: { 'content-type': 'application/json' },\n        body: JSON.stringify(body),\n      })\n  if (!response.ok) {\n    throw new Error('pet ' + path + ' failed: ' + response.status)\n  }\n  return (await response.json()) as T\n}\n\n/** The live host API instance (always defined; failures surface per call). */\nconst petApi: PetHttpApi = {\n  state: (currentSessionId) => petFetch('/api/pet/state'\n    + (currentSessionId === undefined ? '' : '?current=' + encodeURIComponent(currentSessionId))),\n  pets: () => petFetch('/api/pet/pets'),\n  interact: (kind) => petFetch('/api/pet/interact', { kind }),\n  setVisible: (visible) => petFetch('/api/pet/set-visible', { visible }),\n  setConfig: (patch) => petFetch('/api/pet/set-config', patch),\n  setName: (name) => petFetch('/api/pet/set-name', { name }),\n  setPet: (petId) => petFetch('/api/pet/set-pet', { petId }),\n  panelAction: (id) => petFetch('/api/pet/panel-action', { id }),\n  setSkin: (skin) => petFetch('/api/pet/set-skin', skin === undefined ? {} : { skin }),\n  gameplayTouch: (zone) => petFetch('/api/pet/gameplay/touch', zone === undefined ? {} : { zone }),\n  gameplaySetMode: (mode) => petFetch('/api/pet/gameplay/mode', { mode }),\n  gameplayWorkTick: () => petFetch('/api/pet/gameplay/work-tick', {}),\n  gameplayBuy: (item) => petFetch('/api/pet/gameplay/buy', { item }),\n}\n\n/** Poll interval for the host snapshot. */\nconst POLL_MS = 2000\n\n/** Settings namespace of the pet's settings page. It is the profile entry id the Host serves a form for. */\nconst PET_SETTINGS_NS = 'pet'\n\n/** Required services (sessions powers bubble-to-session navigation). */\nexport const inject = ['slots', 'locale', 'connection', 'configForms', 'remote', 'sessions', 'uiWorkspace']\n\n/** Re-exported for consumers that type against the injected face. */\nexport type { PetInjected, PetDockEntryProps } from './PetDockEntry.tsx'\nexport type { PetSpriteProps } from './PetSprite.tsx'\nexport type { PetUiState, PetFeedback } from './pet-store.ts'\nexport type { PetSettingsCardFace, PetSettingsCardState } from './PetSettingsCard.tsx'\nexport type { PetSettingsSectionProps } from './PetSettingsCard.tsx'\nexport type { PetDefinition } from '../registry.ts'\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    /**\n     * Optional family binder provided by dsh-web-settings; absent when that\n     * group plugin is not installed, so callers fall back to the shared\n     * per-entry form.\n     */\n    webUiSettings?: {\n      bind<S>(spec: { namespace: string; decode?: (section: unknown) => S | undefined }): ConfigForm<S>\n    }\n  }\n}\n\n/**\n * The profile entry ids a pet install is served under, most specific first. The\n * family bundle renames child rows, so a standalone install and an aggregate\n * one answer to different ids for the same 'pet' namespace.\n */\nconst AGGREGATE_ENTRY_ID = 'web-ui-pet'\nconst PET_ENTRY_IDS: readonly string[] = [AGGREGATE_ENTRY_ID, 'ui-pet', PET_SETTINGS_NS]\n\n/** How long the deferred form keeps retrying before it settles on the fallback. */\nexport const BINDER_RETRY_MS = 250\nconst BINDER_ATTEMPTS = 24\n\n/** The snapshot an unresolved (or resolvable-but-unbound) form publishes. */\nfunction pendingSnapshot<T>(status: 'loading' | 'unavailable'): ConfigFormSnapshot<T> {\n  return { status, value: undefined, base: undefined, user: undefined, revision: undefined, writable: false }\n}\n\n/**\n * A ConfigForm that late-binds to the family settings binder.\n *\n * The binder service (dsh